    chkApplyNetwork = @{ it = "Applica le impostazioni della pagina Rete. Senza questa spunta la pagina resta solo informativa."; en = "Applies the settings on the Network page. Without this box the page is informational only." }
    chkApplyDns = @{ it = "Usa i server DNS scelti nel menu. Pagine che si aprono più in fretta e, con alcuni servizi, meno pubblicità."; en = "Uses the DNS servers chosen in the menu. Pages open faster and, with some providers, fewer ads." }
    chkNetPowerSave = @{ it = "La scheda di rete non va più a risparmio energetico. Connessione più stabile e ping più regolare."; en = "The network card no longer goes into power saving. A steadier connection and more even ping." }
    chkDisableIPv6 = @{ it = "Spegne il protocollo IPv6. Utile solo se il tuo operatore non lo usa e hai problemi di connessione."; en = "Turns off IPv6. Useful only if your provider does not use it and you have connection issues." }
    chkStorageProfile = @{ it = "Applica le ottimizzazioni pensate per il tipo di disco scelto: SSD o disco meccanico."; en = "Applies the optimizations meant for the chosen drive type: SSD or hard disk." }
    chkDiskCleanup = @{ it = "Elimina file di sistema superflui e vecchie versioni degli aggiornamenti. Recupera spazio, a volte diversi GB."; en = "Deletes unneeded system files and old update versions. Recovers space, sometimes several GB." }
    chkTempCleanup = @{ it = "Svuota le cartelle dei file temporanei. Più spazio libero."; en = "Empties the temporary file folders. More free space." }
    chkSmartChkdsk = @{ it = "Controlla il disco al prossimo riavvio nel modo adatto a SSD o disco meccanico. Corregge errori del file system."; en = "Checks the disk at the next restart in the way that suits SSDs or hard disks. Fixes file system errors." }
    chkStorageSense = @{ it = "Windows non cancella più file da solo per fare spazio. Decidi tu cosa eliminare."; en = "Windows no longer deletes files on its own to make room. You decide what to remove." }
    chkReservedStorage = @{ it = "Libera lo spazio che Windows tiene da parte per gli aggiornamenti, circa 7 GB."; en = "Frees the space Windows keeps aside for updates, about 7 GB." }
    chkFastStartup = @{ it = "Ogni spegnimento diventa uno spegnimento completo. Risolve problemi di driver e dual boot."; en = "Every shutdown becomes a full shutdown. Fixes driver and dual-boot problems." }
    chkHibernation = @{ it = "Spegne l'ibernazione e libera sul disco C: uno spazio pari a gran parte della RAM."; en = "Turns off hibernation and frees space on C: roughly equal to most of your RAM." }
    chkS0Sleep = @{ it = "In sospensione il PC non resta collegato a internet. Consuma meno e non si sveglia da solo."; en = "While asleep the PC stays offline. Uses less power and does not wake by itself." }
    chkS3Sleep = @{ it = "Usa la sospensione classica al posto di quella moderna. Il portatile non si scalda nello zaino."; en = "Uses classic sleep instead of modern standby. The laptop does not heat up in your bag." }
    chkGpuTdr = @{ it = "Dà alla scheda video più tempo prima che Windows la riavvii. Meno schermi neri durante carichi pesanti."; en = "Gives the graphics card more time before Windows resets it. Fewer black screens under heavy load." }
    chkGpuMsi = @{ it = "Cambia il modo in cui la scheda video segnala al processore. Può ridurre la latenza."; en = "Changes how the graphics card signals the processor. Can reduce latency." }
    chkNvTelemetry = @{ it = "Ferma l'invio dei dati di utilizzo a NVIDIA. Meno processi in background."; en = "Stops usage data being sent to NVIDIA. Fewer background processes." }
    chkNvGfe = @{ it = "GeForce Experience non parte più da solo all'avvio. Avvio più leggero."; en = "GeForce Experience no longer starts by itself. A lighter startup." }
    chkNvPerfMode = @{ it = "La scheda NVIDIA resta alla massima frequenza. Prestazioni costanti, consumi più alti."; en = "Keeps the NVIDIA card at full clock speed. Steady performance, higher power draw." }
    chkNvUpdates = @{ it = "Il driver NVIDIA non controlla più da solo gli aggiornamenti."; en = "The NVIDIA driver no longer checks for updates on its own." }
    chkAmdUx = @{ it = "Ferma l'invio dei dati di utilizzo ad AMD."; en = "Stops usage data being sent to AMD." }
    chkAmdBloat = @{ it = "Evita che i programmi accessori AMD partano con Windows. Avvio più leggero."; en = "Keeps AMD companion programs from starting with Windows. A lighter startup." }
    chkIntelBloat = @{ it = "I servizi accessori della grafica Intel partono solo quando servono."; en = "Intel graphics companion services start only when needed." }
    chkSvcSysMain = @{ it = "Windows smette di precaricare in memoria le app che usi spesso. Utile su SSD veloci, dove non serve."; en = "Windows stops preloading your frequent apps into memory. Useful on fast SSDs, where it is not needed." }
    chkSvcDiag = @{ it = "Ferma i servizi che analizzano problemi e prestazioni in background."; en = "Stops the services that analyse problems and performance in the background." }
    chkSvcErrors = @{ it = "Ferma il servizio che raccoglie e invia i rapporti di errore."; en = "Stops the service that collects and sends error reports." }
    chkSvcPca = @{ it = "Ferma il servizio che controlla la compatibilità dei vecchi programmi."; en = "Stops the service that checks old programs for compatibility." }
    chkSvcDiscovery = @{ it = "Il PC smette di cercare dispositivi sulla rete locale. Meno traffico, ma stampanti e TV di rete potrebbero non comparire."; en = "The PC stops searching for devices on the local network. Less traffic, but network printers and TVs may not show up." }
    chkSvcSensors = @{ it = "Ferma i servizi di sensori e posizione. Utile sui PC fissi, che non li hanno."; en = "Stops sensor and location services. Useful on desktops, which do not have them." }
    chkSvcSmartCard = @{ it = "Ferma i servizi per le smart card. Non servono se non usi lettori di tessere."; en = "Stops smart card services. Not needed if you do not use card readers." }
    chkSvcParental = @{ it = "Ferma controllo genitori e programma Insider. Non servono su un PC personale."; en = "Stops parental controls and the Insider program. Not needed on a personal PC." }
    chkSvcHyperV = @{ it = "Ferma i servizi delle macchine virtuali. Tienili se usi Hyper-V, WSL o l'emulatore Android."; en = "Stops virtual machine services. Keep them if you use Hyper-V, WSL or the Android emulator." }
    chkSvcPrint = @{ it = "Ferma il servizio di stampa. Da usare solo se non stampi mai da questo PC."; en = "Stops the print service. Only if you never print from this PC." }
    chkSvcSearch = @{ it = "Ferma l'indicizzazione dei file. Meno lavoro del disco, ma la ricerca diventa lenta."; en = "Stops file indexing. Less disk work, but search becomes slow." }
    chkSvcRemote = @{ it = "Ferma Desktop remoto e accesso remoto al registro. Più sicurezza se non ti colleghi da fuori."; en = "Stops Remote Desktop and remote registry access. More security if you never connect from outside." }
    chkSvcBiometric = @{ it = "Ferma impronta e riconoscimento del volto. Da evitare se accedi con Windows Hello."; en = "Stops fingerprint and face recognition. Avoid it if you sign in with Windows Hello." }
    chkSvcTouch = @{ it = "Ferma penna e tastiera virtuale. Da evitare su tablet e portatili touch."; en = "Stops pen and the on-screen keyboard. Avoid it on tablets and touch laptops." }
    chkTaskExtra = @{ it = "Spegne una ventina di attività automatiche di Microsoft che non servono. Meno lavoro nascosto."; en = "Turns off about twenty automatic Microsoft tasks you do not need. Less hidden work." }
    chkTaskMaint = @{ it = "Windows non avvia più la manutenzione automatica di notte. Il PC non si sveglia e non rallenta a sorpresa."; en = "Windows no longer runs automatic maintenance at night. The PC does not wake up or slow down unexpectedly." }
    chkTaskDefrag = @{ it = "Ferma l'ottimizzazione automatica dei dischi. Sugli SSD va poi fatta a mano dalla pagina Archiviazione."; en = "Stops automatic drive optimization. On SSDs it then has to be run by hand from the Storage page." }
    chkPrefetch = @{ it = "Windows smette di preparare in anticipo i file dei programmi. Meno scritture sugli SSD."; en = "Windows stops preparing program files in advance. Fewer writes on SSDs." }
    chkFth = @{ it = "Windows smette di applicare correzioni automatiche ai programmi che si bloccano. Comportamento più prevedibile."; en = "Windows stops applying automatic fixes to programs that crash. More predictable behaviour." }
    chkAppCompat = @{ it = "Spegne i controlli di compatibilità sui programmi. Avvio dei programmi un po' più rapido."; en = "Turns off compatibility checks on programs. Programs start slightly faster." }
    chkSvcHostSplit = @{ it = "Raggruppa i servizi di Windows in meno processi. Meno memoria usata e un Gestione attività più leggibile."; en = "Groups Windows services into fewer processes. Less memory used and a tidier Task Manager." }
    chkMemCompression = @{ it = "Windows smette di comprimere la memoria. Meno lavoro del processore, ma serve molta RAM."; en = "Windows stops compressing memory. Less processor work, but you need plenty of RAM." }
    chkWuNoReboot = @{ it = "Gli aggiornamenti non riavviano più il PC mentre lo usi."; en = "Updates no longer restart the PC while you are using it." }
    chkWuDefer = @{ it = "Le nuove versioni di Windows arrivano dopo un anno, quando sono già stabili. Le patch di sicurezza continuano ad arrivare."; en = "New Windows versions arrive after a year, once they are stable. Security patches keep coming." }
    chkWuNoStore = @{ it = "Le app dello Store non si aggiornano più da sole in background."; en = "Store apps no longer update themselves in the background." }
    chkBootQuiet = @{ it = "Avvio senza logo animato. Schermata più pulita e avvio un filo più rapido."; en = "Starts without the animated logo. A cleaner screen and a slightly faster boot." }
    chkBootMenu = @{ it = "Rimette il menu di avvio classico, che permette di entrare in modalità provvisoria con F8."; en = "Brings back the classic boot menu, which lets you enter Safe Mode with F8." }
    chkBootTimeout = @{ it = "Se hai più sistemi installati, il PC parte subito senza aspettare nel menu di scelta."; en = "If several systems are installed, the PC starts right away without waiting in the choice menu." }
    chkBootDynTick = @{ it = "Il processore tiene un ritmo di sistema costante. Su alcuni PC abbassa la latenza, su altri no: va provato."; en = "The processor keeps a constant system tick. On some PCs it lowers latency, on others it does not: test it." }
    chkBootTsc = @{ it = "Rende più precisa la misura del tempo tra i core del processore. Può migliorare la fluidità: va provato."; en = "Makes timekeeping across processor cores more precise. Can improve smoothness: test it." }
    chkAppxBloat = @{ it = "Rimuove app preinstallate come notizie, meteo, mappe e Skype. Più spazio e menu Start più ordinato."; en = "Removes preinstalled apps such as news, weather, maps and Skype. More space and a tidier Start menu." }
    chkAppxXbox = @{ it = "Rimuove le app Xbox e l'overlay di gioco. Da evitare se usi Game Pass."; en = "Removes Xbox apps and the game overlay. Avoid it if you use Game Pass." }
    chkAppxProvision = @{ it = "Le app rimosse non ricompaiono quando si crea un nuovo utente."; en = "Removed apps do not come back when a new user is created." }
    chkSecSmartScreen = @{ it = "Spegne il controllo dei file scaricati. Nessun avviso all'apertura, ma nessuna protezione da file pericolosi."; en = "Turns off the check on downloaded files. No warnings when opening them, but no protection from dangerous files." }
    chkSecSpectre = @{ it = "Toglie le protezioni contro alcune falle dei processori. Più prestazioni, soprattutto sulle CPU vecchie, ma meno sicurezza."; en = "Removes protections against some processor flaws. More performance, especially on older CPUs, but less security." }
    chkSecDefenderIdle = @{ it = "L'antivirus fa le scansioni solo a computer fermo e senza appesantirlo. La protezione in tempo reale resta attiva."; en = "The antivirus scans only when the computer is idle and without weighing it down. Real-time protection stays on." }
    chkRestorePoint = @{ it = "Crea un punto di ripristino prima di applicare. Se qualcosa non va, torni indietro da Ripristino configurazione di sistema."; en = "Creates a restore point before applying. If something goes wrong, you can go back with System Restore." }
    chkAmdUlps = @{ it = "Impedisce alla scheda AMD di spegnersi quando è a riposo. Frequenze pronte e niente micro-scatti al risveglio, consumi un po' più alti."; en = "Stops the AMD card from powering down when idle. Clocks stay ready and no micro-stutter on wake-up, slightly higher power draw." }
    chkMenuSleep = @{ it = "Mostra o nasconde Sospendi nel menu di spegnimento di Start. Il cambio vale subito."; en = "Shows or hides Sleep in the Start power menu. The change applies immediately." }
    chkMenuHibernate = @{ it = "Mostra o nasconde Iberna nel menu di spegnimento di Start. Se l'ibernazione era spenta, viene riattivata."; en = "Shows or hides Hibernate in the Start power menu. If hibernation was off, it is turned back on." }
    chkNvP2 = @{ it = "Il driver non abbassa più le frequenze della memoria quando parte un programma CUDA. Rendering e calcolo più veloci."; en = "The driver stops lowering memory clocks when a CUDA program starts. Faster rendering and compute." }
    chkNvDrsPower = @{ it = "La scheda resta alle frequenze alte invece di rallentare tra un fotogramma e l'altro. Meno cali di FPS."; en = "The card stays at high clocks instead of slowing between frames. Fewer FPS drops." }
    chkNvLowLatency = @{ it = "Il processore prepara un solo fotogramma in anticipo. Il gioco risponde prima ai comandi."; en = "The processor prepares just one frame ahead. The game reacts sooner to your input." }
    chkNvThreaded = @{ it = "I giochi OpenGL distribuiscono il lavoro del driver su più core."; en = "OpenGL games spread the driver's work over several cores." }
    chkNvTexPerf = @{ it = "Il filtro delle texture privilegia la velocità: qualche FPS in più, differenza visiva minima."; en = "Texture filtering favors speed: a few more FPS, minimal visual difference." }
    chkNvAniso = @{ it = "Il filtro anisotropico usa meno campioni dove non si vede la differenza."; en = "Anisotropic filtering takes fewer samples where the difference doesn't show." }
    chkNvShaderCache = @{ it = "Il driver non cancella gli shader compilati: meno scatti quando un gioco carica aree nuove."; en = "The driver keeps compiled shaders: fewer stutters when a game loads new areas." }
    chkNvNoFxaa = @{ it = "Spegne l'antialiasing forzato dal driver e l'overlay fotografico Ansel."; en = "Turns off driver-forced antialiasing and the Ansel photo overlay." }
    chkNvDisplayPower = @{ it = "Il driver non abbassa la luminosità dello schermo per risparmiare energia."; en = "The driver doesn't dim the screen to save power." }
    chkNvHdcp = @{ it = "Toglie la protezione dei contenuti: meno lavoro per la scheda, ma Netflix e simili non vanno in alta risoluzione."; en = "Removes content protection: less work for the card, but Netflix and similar won't play in high resolution." }
    chkNvPreempt = @{ it = "La scheda finisce un lavoro prima di passare al successivo. Può ridurre la latenza, su alcuni PC causa blocchi."; en = "The card finishes a job before switching to the next. It can reduce latency; on some PCs it causes hangs." }
    chkNvDynPstate = @{ it = "La scheda non scende mai di frequenza. Massima reattività, più calore e consumo anche a riposo."; en = "The card never lowers its clocks. Maximum responsiveness, more heat and power even at idle." }
    chkNvLatency = @{ it = "Riduce le attese interne del driver usate per risparmiare energia. Effetto variabile: provalo e misura."; en = "Cuts the driver's internal waits used to save power. The effect varies: try it and measure." }
    chkAmdAntiLag = @{ it = "Il processore non corre avanti rispetto alla scheda video. Comandi più immediati nei giochi."; en = "The processor doesn't run ahead of the graphics card. Snappier controls in games." }
    chkAmdShaderCache = @{ it = "Gli shader compilati restano sempre salvati: meno scatti ai caricamenti."; en = "Compiled shaders are always kept: fewer stutters on loading." }
    chkAmdTexPerf = @{ it = "Il filtro delle texture privilegia la velocità, con differenze minime a vista."; en = "Texture filtering favors speed, with barely visible differences." }
    chkAmdTess = @{ it = "Il driver limita la tassellatura esagerata di alcuni giochi. FPS più alti nelle scene pesanti."; en = "The driver caps some games' excessive tessellation. Higher FPS in heavy scenes." }
    chkAmdFlipQueue = @{ it = "Un solo fotogramma in coda verso lo schermo. Meno ritardo tra mouse e immagine."; en = "Only one frame queued to the screen. Less delay between mouse and image." }
    chkAmdNoFrtc = @{ it = "Toglie il tetto agli FPS impostato dal driver."; en = "Removes the FPS cap set by the driver." }
    chkAmdStutter = @{ it = "La memoria video non entra in risparmio tra un fotogramma e l'altro. Tempi dei fotogrammi più regolari."; en = "Video memory doesn't power down between frames. Steadier frame times." }
    chkAmdAspm = @{ it = "Il collegamento PCIe della scheda resta sempre attivo. Niente micro-ritardi al risveglio."; en = "The card's PCIe link stays always active. No micro-delays on wake-up." }
    chkAmdPowerGating = @{ it = "Le unità della scheda non vengono spente a riposo. Più reattiva, consuma e scalda di più."; en = "The card's units aren't powered off at idle. More responsive, more power and heat." }
    chkAmdDma = @{ it = "Cambia il modo in cui la scheda copia i dati. Su alcune schede riduce gli scatti, su altre li peggiora."; en = "Changes how the card copies data. On some cards it reduces stutter, on others it worsens it." }
    chkAmdPreempt = @{ it = "La scheda finisce un calcolo prima di passare al successivo. Da provare: su alcuni PC causa blocchi."; en = "The card finishes a compute job before the next one. Worth testing: on some PCs it causes hangs." }
}

