foreach ($lang in $script:Tr.Keys) {
    foreach ($entry in $script:Tr[$lang].GetEnumerator()) {
        $kind, $name = $entry.Key -split ':', 2
        $table = switch ($kind) { 'L' { $script:Loc } 'M' { $script:Msg } 'H' { $script:Tips } }
        if ($table.ContainsKey($name)) { $table[$name][$lang] = $entry.Value }
    }
}

