    'pw.incPolicy' = @{ it = 'Con Immediata il processore va subito al massimo quando il carico sale.'; en = 'With Rocket the processor jumps straight to maximum when load rises.' }
    'pw.decPolicy' = @{ it = 'Un passo alla volta tiene alta la frequenza più a lungo tra un picco e l''altro.'; en = 'Single step keeps the frequency high longer between spikes.' }
    'pw.pcie' = @{ it = 'Spento, scheda video e SSD NVMe non entrano in stati a basso consumo: niente micro-ritardi.'; en = 'Off, graphics card and NVMe SSD skip low-power states: no micro-delays.' }
    'pw.usbSuspend' = @{ it = 'Spenta, mouse, tastiere e schede audio USB non si addormentano mai.'; en = 'Off, USB mice, keyboards and audio interfaces never doze off.' }
    'pw.usb3Lpm' = @{ it = 'Spento, i dispositivi USB 3 rispondono senza ritardi di risveglio.'; en = 'Off, USB 3 devices respond without wake-up delays.' }
    'pw.wifi' = @{ it = 'Prestazioni massime evita cali di ping dovuti al risparmio della scheda.'; en = 'Maximum performance avoids ping spikes caused by adapter power saving.' }
    'pw.disk' = @{ it = 'Su Mai i dischi meccanici non si fermano: niente attesa quando li riapri.'; en = 'On Never, hard drives don''t spin down: no wait when you open them again.' }
    'pw.display' = @{ it = 'Dopo quanto tempo di inattività si spegne il monitor.'; en = 'How long without activity before the monitor turns off.' }
    'pw.sleep' = @{ it = 'Dopo quanto tempo di inattività il PC va in sospensione.'; en = 'How long without activity before the PC goes to sleep.' }
    'pw.hibAfter' = @{ it = 'Dopo quanto tempo di sospensione il PC salva tutto su disco e si spegne.'; en = 'How long asleep before the PC saves everything to disk and powers off.' }
    'pw.hybrid' = @{ it = 'Salva la sessione anche su disco: se manca la corrente non perdi il lavoro.'; en = 'Also saves the session to disk: a power cut doesn''t lose your work.' }
    'pw.wake' = @{ it = 'Decide se le attività pianificate possono accendere il PC di notte.'; en = 'Decides whether scheduled tasks can wake the PC at night.' }
    'pw.powerBtn' = @{ it = 'Cosa fa il PC quando premi il pulsante di accensione.'; en = 'What the PC does when you press the power button.' }
    'pw.lid' = @{ it = 'Cosa fa il portatile quando chiudi il coperchio.'; en = 'What the laptop does when you close the lid.' }
    'pw.videoBias' = @{ it = 'Sui portatili evita che i video scendano di qualità per risparmiare batteria.'; en = 'On laptops stops videos dropping quality to save battery.' }
    'pw.videoPlay' = @{ it = 'Ottimizza la qualità mantiene immagini fluide e nitide.'; en = 'Optimize quality keeps pictures smooth and sharp.' }
}

