# Esegue la coda di azioni con avanzamento e riepilogo. La usano sia
# «Applica modifiche» sia «Annulla selezionate».
function Invoke-ActionQueue {
    param([string]$Header)
    $total = $script:Actions.Count
    $script:Running = $true
    $btnRun.IsEnabled = $false; $btnUndo.IsEnabled = $false
    $script:OkCount = 0; $script:WarnCount = 0; $script:SkipCount = 0
    $txtProgressLabel.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#FFF2F2F5'))
    Update-Progress 0 $total (T 'starting')
    Write-Log "======================================================="
    Write-Log "[AVVIO] $Header - $total operazioni in coda."

    $i = 0
    foreach ($action in $script:Actions) {
        $i++
        Update-Progress $i $total $action.Name
        Write-Log "[$i/$total] $($action.Name)"
        try { & $action.Do } catch { Write-Log "[ERRORE] $($action.Name): $($_.Exception.Message)" }
    }

    Update-Progress $total $total (T 'done')
    Show-RunSummary
    Write-Log "======================================================="
    Write-Log "[$(T 'summary')] OK: $script:OkCount | Saltati: $script:SkipCount | Avvisi ed errori: $script:WarnCount"


    $script:Running = $false
    Show-StorageInventory
    Update-PowerPlanLabel
    Update-ApplyButton
}

$btnUndo.Add_Click({
    Build-UndoActions
    $total = $script:Actions.Count
    if ($total -eq 0) {
        Write-Log "[AVVISO] $(T 'nothing')"
        return
    }
    if (-not (Show-Dialog (T 'confirmTitle') (T 'undoAsk') 'ask' ((T 'selCount') -f $total))) { return }
    Invoke-ActionQueue "Tweak Andrew v7.1 - ANNULLA"
})


# ------------------------------------------------------------------------------
# 16. CORNICE DELLA FINESTRA
# ------------------------------------------------------------------------------
# Tema nero pieno: niente backdrop acrilico, che su uno sfondo opaco non si
# vedrebbe e lasciava intravedere il desktop negli angoli. A DWM si chiedono
# solo il bordo scuro e gli angoli arrotondati di Windows 11.
Add-Type -Namespace TweakAndrew -Name Dwm -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("dwmapi.dll")]
public static extern int DwmSetWindowAttribute(System.IntPtr hwnd, int attr, ref int value, int size);
'@ -ErrorAction SilentlyContinue

function Enable-DarkFrame {
    try {
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
        if ($hwnd -eq [System.IntPtr]::Zero) { return }
        $dark = 1
        [TweakAndrew.Dwm]::DwmSetWindowAttribute($hwnd, 20, [ref]$dark, 4) | Out-Null
        $round = 2
        [TweakAndrew.Dwm]::DwmSetWindowAttribute($hwnd, 33, [ref]$round, 4) | Out-Null
        # 34 = colore del bordo, in formato 0x00BBGGRR: grigio quasi nero.
        $border = 0x001F1C1C
        [TweakAndrew.Dwm]::DwmSetWindowAttribute($hwnd, 34, [ref]$border, 4) | Out-Null
    } catch {}
}

