function Get-PowerPlanList {
    $result = @()
    try {
        foreach ($line in (powercfg /list)) {
            $m = [regex]::Match([string]$line, '([0-9a-fA-F]{8}-[0-9a-fA-F-]{27})\s*\(([^\)]*)\)\s*(\*)?')
            if ($m.Success) {
                $result += [pscustomobject]@{
                    Guid   = $m.Groups[1].Value
                    Name   = $m.Groups[2].Value.Trim()
                    Active = $m.Groups[3].Success
                }
            }
        }
    } catch {}
    return $result
}

function Find-PowerPlan {
    param([string]$Pattern)
    if ([string]::IsNullOrWhiteSpace($Pattern)) { return $null }
    return (Get-PowerPlanList | Where-Object { $_.Name -match $Pattern } | Select-Object -First 1)
}

function Import-EmbeddedPlan {
    param([string]$Key)
    if (-not $script:PlanData.ContainsKey($Key)) {
        Write-Log "[ERRORE] Piano '$Key' non presente nel catalogo incorporato."
        return
    }
    $temp = Join-Path $env:TEMP "TweakAndrew_$Key.pow"
    try {
        [System.IO.File]::WriteAllBytes($temp, [System.Convert]::FromBase64String($script:PlanData[$Key]))
        powercfg -import "$temp" | Out-Null
        Write-Log "[OK] Piano '$Key' importato."
    } catch {
        Write-Log "[ERRORE] Importazione di '$Key': $($_.Exception.Message)"
    } finally {
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
}

function Enable-CatalogPlan {
    param($Entry)
    try {
        $guid = $null
        switch ($Entry.Kind) {
            'builtin' { $guid = $Entry.Guid }
            'duplicate' {
                $found = Find-PowerPlan $Entry.Match
                if (-not $found) {
                    powercfg -duplicatescheme $Entry.Guid | Out-Null
                    $found = Find-PowerPlan $Entry.Match
                }
                if ($found) { $guid = $found.Guid }
            }
            'embedded' {
                $found = Find-PowerPlan $Entry.Match
                if (-not $found) {
                    Import-EmbeddedPlan $Entry.Key
                    $found = Find-PowerPlan $Entry.Match
                }
                if ($found) { $guid = $found.Guid }
            }
        }
        if ($guid) {
            powercfg -setactive $guid | Out-Null
            Write-Log "[OK] Piano attivo: $($Entry.Name) ($guid)."
        } else {
            Write-Log "[AVVISO] Piano '$($Entry.Name)' non trovato dopo l'installazione."
        }
    } catch {
        Write-Log "[ERRORE] Piano '$($Entry.Name)': $($_.Exception.Message)"
    }
    Update-PowerPlanLabel
    Show-PlanList
}

function New-Brush([string]$hex) {
    return (New-Object System.Windows.Media.BrushConverter).ConvertFromString($hex)
}

# Le righe dell'elenco si creano a runtime: venticinque schede scritte a mano nel
# markup sarebbero illeggibili e andrebbero ritoccate a ogni piano aggiunto.
function Add-PlanRow {
    param($Entry, $Parent)

    $card = New-Object System.Windows.Controls.Border
    $card.Style = $window.FindResource("GlassInner")
    $card.Margin = New-Object System.Windows.Thickness(0, 0, 0, 8)
    $card.Padding = New-Object System.Windows.Thickness(14, 11, 12, 11)

    $grid = New-Object System.Windows.Controls.Grid
    $c1 = New-Object System.Windows.Controls.ColumnDefinition
    $c1.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $c2 = New-Object System.Windows.Controls.ColumnDefinition
    $c2.Width = [System.Windows.GridLength]::Auto
    $grid.ColumnDefinitions.Add($c1) | Out-Null
    $grid.ColumnDefinitions.Add($c2) | Out-Null

    $texts = New-Object System.Windows.Controls.StackPanel
    $texts.Margin = New-Object System.Windows.Thickness(0, 0, 12, 0)

    $title = New-Object System.Windows.Controls.TextBlock
    $title.Text = [string]$Entry.Name
    $title.FontFamily = New-Object System.Windows.Media.FontFamily("Raleway, Segoe UI")
    $title.FontWeight = [System.Windows.FontWeights]::SemiBold
    $title.FontSize = 13
    $title.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $title.Foreground = New-Brush "#FFF2F2F5"

    $desc = New-Object System.Windows.Controls.TextBlock
    $desc.Text = [string]$Entry.Desc
    $desc.Style = $window.FindResource("SubTitle")
    $desc.Margin = New-Object System.Windows.Thickness(0, 3, 0, 0)

    $texts.Children.Add($title) | Out-Null
    $texts.Children.Add($desc) | Out-Null
    [System.Windows.Controls.Grid]::SetColumn($texts, 0)

    $btn = New-Object System.Windows.Controls.Button
    $btn.Style = $window.FindResource("GhostBtn")
    $btn.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $btn.MinWidth = 104
    $btn.Tag = $Entry
    [System.Windows.Controls.Grid]::SetColumn($btn, 1)

    $isActive = $false
    if ($Entry.Kind -eq 'builtin') {
        $isActive = ($script:ActivePlanGuid -eq $Entry.Guid)
    } elseif ($script:ActivePlanName -and $Entry.Match) {
        $isActive = ($script:ActivePlanName -match $Entry.Match)
    }

    if ($isActive) {
        $btn.Content = T 'planActive'
        $btn.IsEnabled = $false
        $card.BorderBrush = New-Brush "#FFFFC53D"
        $card.Background = New-Brush "#1FFFC53D"
    } else {
        $btn.Content = T 'planApply'
        $btn.Add_Click({ Enable-CatalogPlan $this.Tag })
    }

    $grid.Children.Add($texts) | Out-Null
    $grid.Children.Add($btn) | Out-Null
    $card.Child = $grid
    $Parent.Children.Add($card) | Out-Null
}

function Add-PlanGroupTitle {
    param([string]$Text, $Parent, [string]$Color)
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $Text
    $t.Style = $window.FindResource("CardTitle")
    if ($Color) { $t.Foreground = New-Brush $Color }
    $t.Margin = New-Object System.Windows.Thickness(0, 6, 0, 10)
    $Parent.Children.Add($t) | Out-Null
}

function Show-PlanList {
    if ($null -eq $panPlans) { return }
    $current = Get-PowerPlanList | Where-Object { $_.Active } | Select-Object -First 1
    $script:ActivePlanName = if ($current) { $current.Name } else { "" }
    $script:ActivePlanGuid = if ($current) { $current.Guid } else { "" }

    $panPlans.Children.Clear()

    Add-PlanGroupTitle (T 'planTop') $panPlans "#FFFFC53D"
    foreach ($e in ($script:PlanCatalog | Where-Object { $_.Group -eq 'top' })) { Add-PlanRow $e $panPlans }

    Add-PlanGroupTitle (T 'planWindows') $panPlans "#FF8E8E98"
    foreach ($e in ($script:PlanCatalog | Where-Object { $_.Group -eq 'windows' })) { Add-PlanRow $e $panPlans }

    Add-PlanGroupTitle (T 'planTest') $panPlans "#FFE0A25E"
    $hint = New-Object System.Windows.Controls.TextBlock
    $hint.Text = T 'planTestHint'
    $hint.Style = $window.FindResource("SubTitle")
    $hint.Foreground = New-Brush "#FFD9A470"
    $hint.Margin = New-Object System.Windows.Thickness(0, -4, 0, 12)
    $panPlans.Children.Add($hint) | Out-Null
    foreach ($e in ($script:PlanCatalog | Where-Object { $_.Group -eq 'test' })) { Add-PlanRow $e $panPlans }
}

$btnRefreshPlans.Add_Click({ Update-PowerPlanLabel; Show-PlanList })

# Toglie i piani di prova importati. Un piano attivo non si puo' eliminare,
# quindi prima si torna su Bilanciato.
$btnRemoveTestPlans.Add_Click({
    if (-not (Show-Dialog (T 'confirmTitle') (T 'planRemoveAsk') 'warn')) { return }

    powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e | Out-Null
    $removed = 0
    foreach ($entry in ($script:PlanCatalog | Where-Object { $_.Group -eq 'test' })) {
        $found = Find-PowerPlan $entry.Match
        if ($found) {
            try { powercfg -delete $found.Guid | Out-Null; $removed++ } catch {}
        }
    }
    Write-Log "[OK] Piani di prova rimossi: $removed."
    Update-PowerPlanLabel
    Show-PlanList
})

# ------------------------------------------------------------------------------
# 19. SCHEDA VIDEO
# ------------------------------------------------------------------------------
$script:GpuVendor = 'Unknown'
# Tutte le marche presenti nel PC: un portatile ha spesso Intel integrata piu'
# una scheda dedicata, e le voci dell'una non devono finire sull'altra.
$script:GpuVendors = @()

function Show-GpuInfo {
    if ($null -eq $txtGpuDetected) { return }
    try {
        $gpus = @(Get-CimInstance Win32_VideoController -ErrorAction Stop |
                  Where-Object { $_.Name -and $_.PNPDeviceID -notmatch '^ROOT\\' })
    } catch { $gpus = @() }

    if ($gpus.Count -eq 0) {
        $txtGpuDetected.Text = T 'gpuNone'
        $script:GpuVendor = 'Unknown'
        $script:GpuVendors = @()
        return
    }

    $names = ($gpus | ForEach-Object { $_.Name }) -join ' '
    if     ($names -match 'NVIDIA|GeForce|RTX|GTX|Quadro') { $script:GpuVendor = 'NVIDIA' }
    elseif ($names -match 'Radeon|AMD|ATI')                { $script:GpuVendor = 'AMD' }
    elseif ($names -match 'Intel')                         { $script:GpuVendor = 'Intel' }
    else                                                   { $script:GpuVendor = 'Unknown' }

    $script:GpuVendors = @(
        @(@{ V = 'NVIDIA'; P = 'NVIDIA|GeForce|RTX|GTX|Quadro' }, @{ V = 'AMD'; P = 'Radeon|AMD|ATI' }, @{ V = 'Intel'; P = 'Intel' }) |
        Where-Object { $names -match $_.P } | ForEach-Object { $_.V }
    )

    $lines = foreach ($g in $gpus) {
        $data = if ($g.DriverDate) { ([datetime]$g.DriverDate).ToString('dd/MM/yyyy') } else { '?' }
        "  $($g.Name)`n    driver $($g.DriverVersion) del $data"
    }
    $txtGpuDetected.Text = "$(T 'gpuVendor') $($script:GpuVendor)`n" + ($lines -join "`n")
}

$btnDetectGpu.Add_Click({ Show-GpuInfo; Write-Log "[INFO] Scheda video: $($script:GpuVendor)." })

# La scheda dichiara che le voci del produttore sbagliato vengono ignorate:
# senza questo controllo scriveva comunque le chiavi.
function Test-Gpu {
    param([string]$Vendor, [string]$Label)
    if ($script:GpuVendors -contains $Vendor) { return $true }
    Write-Log "[SALTATO] $Label - nessuna scheda $Vendor rilevata."
    return $false
}

# Disattiva un elenco di attivita' pianificate, saltando quelle non presenti.
# Le attivita' nella radice hanno percorso "\": Split-Path restituisce gia' la
# barra, quindi aggiungerne un'altra dava "\\" e non trovava mai nulla.
function Disable-Tasks {
    param([string[]]$Paths, [string]$Label)
    $n = 0
    foreach ($t in $Paths) {
        try {
            $folder = Split-Path $t -Parent
            if ([string]::IsNullOrEmpty($folder)) { $folder = '\' }
            if (-not $folder.EndsWith('\')) { $folder = "$folder\" }
            $name = Split-Path $t -Leaf
            Disable-ScheduledTask -TaskPath $folder -TaskName $name -ErrorAction Stop | Out-Null
            $n++
        } catch {}
    }
    if ($n -gt 0) { Write-Log "[OK] $Label - attivita' disattivate: $n." }
    else          { Write-Log "[SALTATO] $Label - nessuna attivita' presente." }
}


# ------------------------------------------------------------------------------
# 19b. CACHE SHADER
# ------------------------------------------------------------------------------
# Ogni driver tiene gli shader compilati in cartelle sue. Sono dati rigenerabili:
# cancellarli non tocca i giochi, costa solo una ricompilazione al primo avvio.
function Get-ShaderCachePaths {
    $l = $env:LOCALAPPDATA
    $paths = @(
        "$l\NVIDIA\DXCache",
        "$l\NVIDIA\GLCache",
        "$l\NVIDIA Corporation\NV_Cache",
        "$env:ProgramData\NVIDIA Corporation\NV_Cache",
        "$l\AMD\DxCache",
        "$l\AMD\DxcCache",
        "$l\AMD\GLCache",
        "$l\AMD\VkCache",
        "$l\Intel\ShaderCache",
        "$l\D3DSCache"
    )
    return @($paths | Where-Object { Test-Path -LiteralPath $_ })
}

function Measure-Folder {
    param([string]$Path)
    try {
        $sum = (Get-ChildItem -LiteralPath $Path -Recurse -Force -File -ErrorAction SilentlyContinue |
                Measure-Object -Property Length -Sum).Sum
        if ($null -eq $sum) { return 0 }
        return [long]$sum
    } catch { return 0 }
}

function Format-Size {
    param([long]$Bytes)
    if ($Bytes -ge 1GB) { return ("{0:N1} GB" -f ($Bytes / 1GB)) }
    return ("{0:N0} MB" -f ($Bytes / 1MB))
}

function Show-ShaderCache {
    if ($null -eq $txtShaderSize) { return }
    $paths = Get-ShaderCachePaths
    if ($paths.Count -eq 0) {
        $txtShaderSize.Text = T 'shaderNone'
        return
    }
    $txtShaderSize.Text = T 'shaderScanning'
    [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background)

    $totale = 0
    $righe = foreach ($p in $paths) {
        $b = Measure-Folder $p
        $totale += $b
        "  {0,-14}{1,9}" -f (Split-Path $p -Leaf), (Format-Size $b)
    }
    $txtShaderSize.Text = ($righe -join "`n") + "`n  " + ("-" * 23) + "`n" +
                          ("  {0,-14}{1,9}" -f (T 'shaderTotal'), (Format-Size $totale))
}

$btnShaderScan.Add_Click({ Show-ShaderCache })

$btnShaderClear.Add_Click({
    if (-not (Show-Dialog (T 'confirmTitle') (T 'shaderAsk') 'warn')) { return }

    $liberati = 0
    foreach ($p in (Get-ShaderCachePaths)) {
        $prima = Measure-Folder $p
        # Si svuota la cartella, non la si elimina: il driver la ricrea comunque,
        # ma se manca qualche gioco puo' lamentarsi al primo avvio.
        Get-ChildItem -LiteralPath $p -Force -ErrorAction SilentlyContinue |
            Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        $dopo = Measure-Folder $p
        $liberati += ($prima - $dopo)
        Write-Log ("[OK] {0} - liberati {1:N0} MB." -f (Split-Path $p -Leaf), (($prima - $dopo) / 1MB))
    }
    Write-Log ("[OK] Cache shader svuotata: {0:N0} MB liberati in totale." -f ($liberati / 1MB))
    Show-ShaderCache
})

# ------------------------------------------------------------------------------
# 19c. FUNZIONI NASCOSTE DI WINDOWS
# ------------------------------------------------------------------------------
# Stesso meccanismo di ViVeTool: si scrive un override sotto FeatureManagement.
# EnabledState 2 = funzione attiva, 1 = disattiva. Togliere la chiave rimette il
# comportamento predefinito della build.
$script:FeatureRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\FeatureManagement\Overrides\4'

function Set-WindowsFeature {
    param([string]$Id, [ValidateSet('on','off','reset')][string]$State)
    $path = "$script:FeatureRoot\$Id"
    try {
        if ($State -eq 'reset') {
            if (Test-Path -LiteralPath $path) {
                Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop
                Write-Log "[OK] Funzione $Id riportata al predefinito."
            } else {
                Write-Log "[SALTATO] Funzione $Id - nessuna modifica da togliere."
            }
            return
        }
        $enabled = if ($State -eq 'on') { 2 } else { 1 }
        if (-not (Test-Path -LiteralPath $path)) { New-Item -Path $path -Force -ErrorAction Stop | Out-Null }
        foreach ($v in @(
            @{ N = 'EnabledState';        V = $enabled },
            @{ N = 'EnabledStateOptions'; V = 0 },
            @{ N = 'Variant';             V = 0 },
            @{ N = 'VariantPayload';      V = 0 },
            @{ N = 'VariantPayloadKind';  V = 0 })) {
            New-ItemProperty -LiteralPath $path -Name $v.N -Value $v.V -PropertyType DWord -Force -ErrorAction Stop | Out-Null
        }
        $parola = if ($State -eq 'on') { T 'featStateOn' } else { T 'featStateOff' }
        Write-Log "[OK] Funzione $Id $parola (serve un riavvio)."
    } catch {
        Write-Log "[ERRORE] Funzione $Id - $($_.Exception.Message)"
    }
}

function Show-FeatureOverrides {
    if ($null -eq $txtFeatList) { return }
    $righe = @()
    try {
        foreach ($k in (Get-ChildItem -LiteralPath $script:FeatureRoot -ErrorAction SilentlyContinue)) {
            $stato = Get-RegOrNull $k.PSPath 'EnabledState'
            $parola = switch ($stato) {
                2 { T 'featStateOn' }
                1 { T 'featStateOff' }
                default { "?" }
            }
            $righe += "  $($k.PSChildName)  $parola"
        }
    } catch {}
    if ($righe.Count -eq 0) { $txtFeatList.Text = T 'featEmpty' }
    else { $txtFeatList.Text = ($righe -join "`n") }
}

$btnFeatApply.Add_Click({
    $id = ([string]$txtFeatId.Text).Trim()
    if ($id -notmatch '^\d+$') {
        Write-Log "[AVVISO] $(T 'featNeedId')"
        return
    }
    $stato = 'on'
    switch ($cmbFeatState.SelectedIndex) {
        0 { $stato = 'on' }
        1 { $stato = 'off' }
        2 { $stato = 'reset' }
    }
    Set-WindowsFeature $id $stato
    Show-FeatureOverrides
})

$btnFeatList.Add_Click({ Show-FeatureOverrides })

# Scorre le sottochiavi della classe display: i valori della GPU stanno li'.
# Sottochiavi della classe display, filtrate per produttore: senza filtro un
# valore NVIDIA finiva anche sulla grafica integrata Intel dello stesso PC.
function Get-GpuClassKeys {
    param([string]$Vendor = '')
    $pattern = switch ($Vendor) { 'NVIDIA' { 'NVIDIA' } 'AMD' { 'AMD|Advanced Micro|ATI |Radeon' } 'Intel' { 'Intel' } default { '.' } }
    $base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    Get-ChildItem $base -ErrorAction SilentlyContinue |
        Where-Object { $_.PSChildName -match '^\d{4}$' } |
        Where-Object {
            $p = Get-ItemProperty -LiteralPath $_.PSPath -ErrorAction SilentlyContinue
            ("$($p.ProviderName) $($p.DriverDesc)") -match $pattern
        }
}

function Set-GpuClassValue {
    param([string]$Name, $Value, [string]$Label, [string]$Vendor = '')
    $n = 0
    foreach ($k in @(Get-GpuClassKeys $Vendor)) {
        try { New-ItemProperty -LiteralPath $k.PSPath -Name $Name -Value $Value -PropertyType DWord -Force -ErrorAction Stop | Out-Null; $n++ } catch {}
    }
    if ($n -gt 0) { Write-Log "[OK] $Label - schede aggiornate: $n." }
    else { Write-Log "[SALTATO] $Label - nessuna scheda corrispondente." }
}

# ------------------------------------------------------------------------------
# 22. AVVIO DEL SISTEMA — ritorno ai valori predefiniti
# ------------------------------------------------------------------------------
# deletevalue toglie la voce dalla configurazione: Windows torna al suo
# comportamento di fabbrica, che non e' lo stesso di scriverci il valore
# opposto. Le voci mai impostate rispondono con un errore, ed e' normale.
$btnBootReset.Add_Click({
    if (-not (Show-Dialog (T 'confirmTitle') (T 'bootResetAsk') 'warn')) { return }
    foreach ($arg in @(
        '/deletevalue {current} quietboot',
        '/deletevalue {current} bootlog',
        '/deletevalue {current} bootmenupolicy',
        '/deletevalue disabledynamictick',
        '/deletevalue tscsyncpolicy')) {
        Start-Process -FilePath "$env:SystemRoot\System32\bcdedit.exe" -ArgumentList $arg `
                      -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue | Out-Null
    }
    Start-Process -FilePath "$env:SystemRoot\System32\bcdedit.exe" -ArgumentList '/timeout 30' `
                  -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue | Out-Null
    Write-Log "[OK] $(T 'bootResetDone')"
})

# ------------------------------------------------------------------------------
# 19d. PROFILO GLOBALE DEL DRIVER NVIDIA (DRS)
# ------------------------------------------------------------------------------
# Le stesse impostazioni del Pannello di controllo NVIDIA e di Profile Inspector,
# scritte con l'API ufficiale del driver (nvapi64.dll): nessun programma esterno.
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace TweakAndrew {
public static class NvDrs {
    [DllImport("nvapi64.dll", EntryPoint = "nvapi_QueryInterface", CallingConvention = CallingConvention.Cdecl)]
    static extern IntPtr QueryInterface(uint id);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int NoArg();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int OutPtr(out IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int OnePtr(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int PtrOutPtr(IntPtr h, out IntPtr p);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int SetFn(IntPtr h, IntPtr p, IntPtr s);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int GetFn(IntPtr h, IntPtr p, uint id, IntPtr s);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int IdFn(IntPtr h, IntPtr p, uint id);

    const int Size = 0x3020;
    static T Fn<T>(uint id) where T : class {
        IntPtr p = QueryInterface(id);
        if (p == IntPtr.Zero) throw new Exception("funzione NVAPI assente 0x" + id.ToString("X8"));
        return Marshal.GetDelegateForFunctionPointer(p, typeof(T)) as T;
    }
    static void Check(int r, string what) { if (r != 0) throw new Exception(what + ": codice NVAPI " + r); }

    static IntPtr Open(out IntPtr profile) {
        Check(Fn<NoArg>(0x0150E828)(), "Initialize");
        IntPtr h;
        Check(Fn<OutPtr>(0x0694D52E)(out h), "CreateSession");
        Check(Fn<OnePtr>(0x375DBD6B)(h), "LoadSettings");
        Check(Fn<PtrOutPtr>(0xDA8466A0)(h, out profile), "GetBaseProfile");
        return h;
    }
    static void Close(IntPtr h, bool save) {
        try { if (save) Check(Fn<OnePtr>(0xFCBC7E14)(h), "SaveSettings"); }
        finally { Fn<OnePtr>(0xDAD9CFF8)(h); }
    }
    public static bool Available() {
        try { return QueryInterface(0x0150E828) != IntPtr.Zero && Fn<NoArg>(0x0150E828)() == 0; } catch { return false; }
    }
    // Valore attuale nel profilo globale, oppure -1 se resta quello del driver.
    public static long Get(uint id) {
        IntPtr profile; IntPtr h = Open(out profile);
        IntPtr buf = Marshal.AllocHGlobal(Size);
        try {
            for (int i = 0; i < Size; i++) Marshal.WriteByte(buf, i, 0);
            Marshal.WriteInt32(buf, 0, Size | (1 << 16));
            int r = Fn<GetFn>(0x73BF8338)(h, profile, id, buf);
            if (r != 0) return -1;
            return (uint)Marshal.ReadInt32(buf, 8220);
        } finally { Marshal.FreeHGlobal(buf); Close(h, false); }
    }
    public static void Set(uint id, uint value) {
        IntPtr profile; IntPtr h = Open(out profile);
        IntPtr buf = Marshal.AllocHGlobal(Size);
        bool ok = false;
        try {
            for (int i = 0; i < Size; i++) Marshal.WriteByte(buf, i, 0);
            Marshal.WriteInt32(buf, 0, Size | (1 << 16));
            Marshal.WriteInt32(buf, 4100, (int)id);
            Marshal.WriteInt32(buf, 4104, 0);
            Marshal.WriteInt32(buf, 8220, (int)value);
            Check(Fn<SetFn>(0x577DD202)(h, profile, buf), "SetSetting");
            ok = true;
        } finally { Marshal.FreeHGlobal(buf); Close(h, ok); }
    }
    // Riporta l'impostazione al valore del driver.
    public static void Restore(uint id) {
        IntPtr profile; IntPtr h = Open(out profile);
        bool ok = false;
        try {
            int r = Fn<IdFn>(0x53F0381E)(h, profile, id);
            if (r != 0) r = Fn<IdFn>(0xE4A26362)(h, profile, id);
            ok = true;
        } finally { Close(h, ok); }
    }
}
}
'@ -ErrorAction SilentlyContinue

# Impostazioni del profilo usate dalle caselle della pagina Scheda video.
$script:NvProfileSets = @{
    P2         = @(,@(0x50166C5E, 0))
    Power      = @(,@(0x1057EB71, 1))
    LowLatency = @(@(0x0005F543, 2), @(0x10835000, 1), @(0x007BA09E, 1))
    Threaded   = @(,@(0x20C1221E, 1))
    TexPerf    = @(,@(0x00CE2691, 20))
    Aniso      = @(,@(0x00E73211, 1))
    Shader     = @(,@(0x00AC8497, 4294967295))
    NoFxaa     = @(@(0x1074C972, 0), @(0x1075543B, 0))
}

function Set-NvProfile([string]$set, [string]$label) {
    if (-not [TweakAndrew.NvDrs]::Available()) { Write-Log "[SALTATO] $label - driver NVIDIA non disponibile."; return }
    foreach ($pair in $script:NvProfileSets[$set]) {
        try {
            [TweakAndrew.NvDrs]::Set([uint32]$pair[0], [uint32]$pair[1])
            Write-Log ("[OK] $label - 0x{0:X8} = {1}" -f $pair[0], $pair[1])
        } catch { Write-Log "[ERRORE] $label - $($_.Exception.Message)" }
    }
}

function Reset-NvProfile([string]$set, [string]$label) {
    if (-not [TweakAndrew.NvDrs]::Available()) { Write-Log "[SALTATO] $label - driver NVIDIA non disponibile."; return }
    foreach ($pair in $script:NvProfileSets[$set]) {
        try { [TweakAndrew.NvDrs]::Restore([uint32]$pair[0]); Write-Log ("[OK] $label - 0x{0:X8} predefinito" -f $pair[0]) }
        catch { Write-Log "[ERRORE] $label - $($_.Exception.Message)" }
    }
}

# Valori nella sottochiave UMD delle schede AMD: stringhe di cifre in UTF-16.
function Set-AmdUmdValue([string]$Name, [string]$Digits, [string]$Label) {
    $n = 0
    foreach ($k in @(Get-GpuClassKeys 'AMD')) {
        try {
            $umd = Join-Path $k.PSPath 'UMD'
            if (-not (Test-Path -LiteralPath $umd)) { New-Item -Path $umd -Force | Out-Null }
            $bytes = [System.Text.Encoding]::Unicode.GetBytes($Digits)
            New-ItemProperty -LiteralPath $umd -Name $Name -Value ([byte[]]$bytes) -PropertyType Binary -Force | Out-Null
            $n++
        } catch {}
    }
    if ($n -gt 0) { Write-Log "[OK] $Label - schede aggiornate: $n." } else { Write-Log "[SALTATO] $Label - nessuna scheda AMD." }
}

function Remove-AmdUmdValue([string]$Name, [string]$Label) {
    foreach ($k in @(Get-GpuClassKeys 'AMD')) {
        Remove-ItemProperty -LiteralPath (Join-Path $k.PSPath 'UMD') -Name $Name -ErrorAction SilentlyContinue
    }
    Write-Log "[OK] $Label - valore del driver ripristinato."
}

# Pacchetto latenza del driver NVIDIA: valori noti nelle guide di ottimizzazione.
$script:NvLatencyValues = [ordered]@{
    D3PCLatency = 1; F1TransitionLatency = 1; LOWLATENCY = 1; Node3DLowLatency = 1
    PciLatencyTimerControl = 0x20; RMDeepL1EntryLatencyUsec = 1; RmGspcMaxFtuS = 1; RmGspcMinFtuS = 1
    RmGspcPerioduS = 1; RMLpwrEiIdleThresholdUs = 1; RMLpwrGrIdleThresholdUs = 1; RMLpwrGrRgIdleThresholdUs = 1
    RMLpwrMsIdleThresholdUs = 1; VRDirectFlipDPCDelayUs = 1; VRDirectFlipTimingMarginUs = 1
    VRDirectJITFlipMsHybridFlipDelayUs = 1; vrrCursorMarginUs = 1; vrrDeflickerMarginUs = 1; vrrDeflickerMaxUs = 1
}


# ------------------------------------------------------------------------------
# 23. FINESTRE DI DIALOGO NEL TEMA DEL PROGRAMMA
# ------------------------------------------------------------------------------
# Sostituiscono le MessageBox di Windows, che stonavano con il resto
# dell'interfaccia. Scheda scura, icona colorata, due pulsanti; la finestra
# principale si oscura finche' la domanda e' aperta. Invio conferma, Esc annulla.
$script:Dimmer = E 'dimmer'

function Show-Dialog {
    param(
        [string]$Title,
        [string]$Message,
        [ValidateSet('ask','warn','danger')][string]$Kind = 'ask',
        [string]$Detail = ''
    )
    $accent = switch ($Kind) { 'warn' { '#FFFFB86B' } 'danger' { '#FFF87171' } default { '#FF1E90FF' } }
    $glyph  = if ($Kind -eq 'ask') { '?' } else { '!' }

    [xml]$dx = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        ShowInTaskbar="False" ResizeMode="NoResize" SizeToContent="WidthAndHeight"
        WindowStartupLocation="CenterOwner" TextOptions.TextFormattingMode="Ideal" UseLayoutRounding="True">
    <Border Margin="24" CornerRadius="20" Background="#FF101014" BorderBrush="#FF26262C" BorderThickness="1"
            Padding="26,24,24,22" MinWidth="380" MaxWidth="480">
        <Border.Effect>
            <DropShadowEffect BlurRadius="36" ShadowDepth="6" Opacity="0.7" Color="#000000"/>
        </Border.Effect>
        <StackPanel>
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                </Grid.ColumnDefinitions>
                <Border x:Name="dIcon" Width="34" Height="34" CornerRadius="17" VerticalAlignment="Top" Margin="0,0,16,0">
                    <TextBlock x:Name="dGlyph" FontFamily="Raleway, Segoe UI" FontWeight="Bold" FontSize="17"
                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <StackPanel Grid.Column="1">
                    <TextBlock x:Name="dTitle" FontFamily="Raleway, Segoe UI Variable Display, Segoe UI" FontWeight="Bold"
                               FontSize="16" Foreground="#FFF2F2F5" TextWrapping="Wrap" Margin="0,6,0,8"/>
                    <TextBlock x:Name="dMsg" FontFamily="Roboto, Segoe UI" FontSize="13" Foreground="#FFB4B4BE"
                               TextWrapping="Wrap" LineHeight="20"/>
                    <TextBlock x:Name="dDetail" FontFamily="Roboto, Segoe UI" FontSize="12" Margin="0,10,0,0"
                               TextWrapping="Wrap" Visibility="Collapsed"/>
                </StackPanel>
            </Grid>
            <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,22,0,0">
                <Button x:Name="dNo" Height="38" MinWidth="104" Margin="0,0,10,0"/>
                <Button x:Name="dYes" Height="38" MinWidth="120" IsDefault="True"/>
            </StackPanel>
        </StackPanel>
    </Border>
</Window>
'@
    $dlg = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $dx))
    $dlg.Owner = $window
    $brush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($accent))
    $soft  = $brush.Clone(); $soft.Opacity = 0.16
    $dlg.FindName('dIcon').Background = $soft
    $g = $dlg.FindName('dGlyph'); $g.Text = $glyph; $g.Foreground = $brush
    $dlg.FindName('dTitle').Text = $Title
    $dlg.FindName('dMsg').Text = $Message
    if ($Detail) {
        $d = $dlg.FindName('dDetail'); $d.Text = $Detail; $d.Foreground = $brush
        $d.Visibility = [System.Windows.Visibility]::Visible
    }
    $yes = $dlg.FindName('dYes'); $no = $dlg.FindName('dNo')
    $yes.Style = $window.FindResource('PrimaryBtn'); $no.Style = $window.FindResource('GhostBtn')
    $yes.Content = T 'dlgYes'; $no.Content = T 'dlgNo'
    $yes.Add_Click({ $dlg.DialogResult = $true }.GetNewClosure())
    $no.Add_Click({ $dlg.DialogResult = $false }.GetNewClosure())
    $dlg.Add_KeyDown({ if ($_.Key -eq [System.Windows.Input.Key]::Escape) { $dlg.DialogResult = $false } }.GetNewClosure())
    $dlg.Add_MouseLeftButtonDown({ try { $dlg.DragMove() } catch {} }.GetNewClosure())

    if ($null -ne $script:Dimmer) { $script:Dimmer.Visibility = [System.Windows.Visibility]::Visible }
    try { $r = $dlg.ShowDialog() } finally {
        if ($null -ne $script:Dimmer) { $script:Dimmer.Visibility = [System.Windows.Visibility]::Collapsed }
    }
    return ($r -eq $true)
}

# Riepilogo a fine operazioni: niente finestra, una riga nella barra in basso.
# «OK: 0 | 1 | 0» non diceva niente; qui ogni numero ha il suo nome.
function Show-RunSummary {
    $text = (T 'doneSummary') -f $script:OkCount, $script:SkipCount, $script:WarnCount
    if ($script:OkCount -gt 0) { $text += "  " + (T 'doneReboot') }
    $txtProgressLabel.Text = $text
    $color = if ($script:WarnCount -gt 0) { '#FFFFB86B' } else { '#FF2ED3A7' }
    $txtProgressLabel.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($color))
}

# ------------------------------------------------------------------------------
# 24. MENU ARRESTA: SOSPENDI E IBERNA
# ------------------------------------------------------------------------------
# Interruttori a effetto immediato, fuori dalla coda di «Applica»: leggono lo
# stato attuale all'avvio e lo cambiano appena li tocchi. La presenza delle due
# voci nel menu Arresta e' un'impostazione di sistema, non del piano energetico:
# timeout e valori del piano attivo restano come sono.
$script:FlyoutKey = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\FlyoutMenuSettings'
$script:FlyoutPolicy = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer'
$chkMenuSleep = E 'chkMenuSleep'; $chkMenuHibernate = E 'chkMenuHibernate'
$script:LiveLoading = $false

function Read-ShutdownMenu {
    $script:LiveLoading = $true
    $s = Get-RegOrNull $script:FlyoutKey 'ShowSleepOption'
    $h = Get-RegOrNull $script:FlyoutKey 'ShowHibernateOption'
    $hibOn = (Get-RegOrNull 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled') -eq 1
    # Senza valore, Windows mostra Sospendi e nasconde Iberna.
    $chkMenuSleep.IsChecked = ($null -eq $s -or $s -ne 0)
    $chkMenuHibernate.IsChecked = ($h -eq 1 -and $hibOn)
    $script:LiveLoading = $false
}

function Set-ShutdownMenuItem {
    param([string]$Name, [bool]$Show, [string]$Label)
    Set-Reg $script:FlyoutKey $Name ([int]$Show) 'DWord' "$Label - $(if ($Show) { 'visibile' } else { 'nascosta' })" | Out-Null
    # Un criterio con lo stesso nome avrebbe la precedenza e annullerebbe la scelta.
    if ($null -ne (Get-RegOrNull $script:FlyoutPolicy $Name)) { Remove-Reg $script:FlyoutPolicy $Name "$Label (criterio)" }
}

$chkMenuSleep.Add_Click({
    if ($script:LiveLoading) { return }
    Set-ShutdownMenuItem 'ShowSleepOption' ($chkMenuSleep.IsChecked -eq $true) 'Sospendi nel menu Arresta'
})
$chkMenuHibernate.Add_Click({
    if ($script:LiveLoading) { return }
    $show = ($chkMenuHibernate.IsChecked -eq $true)
    if ($show -and (Get-RegOrNull 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled') -ne 1) {
        # La voce compare solo se l'ibernazione esiste: si riattiva il file di ibernazione.
        powercfg /hibernate on | Out-Null
        Write-Log "[OK] Ibernazione riattivata: serve per mostrare la voce Iberna."
    }
    Set-ShutdownMenuItem 'ShowHibernateOption' $show 'Iberna nel menu Arresta'
})

# ------------------------------------------------------------------------------
# 25. PRIORITA' DEL PROCESSORE (Win32PrioritySeparation)
# ------------------------------------------------------------------------------
# Sei bit, tre coppie: durata del quanto (breve/lunga), quanto fisso o
# variabile, e quanto vantaggio dare alla finestra in primo piano.
$script:PsPath = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
$cmbPsPreset = E 'cmbPsPreset'; $txtPsCustom = E 'txtPsCustom'; $txtPsDecoded = E 'txtPsDecoded'
$txtPsCurrent = E 'txtPsCurrent'; $btnPsApply = E 'btnPsApply'; $btnPsDefault = E 'btnPsDefault'

function Format-PrioritySeparation([int]$v) {
    $interval = ($v -shr 4) -band 3
    $length   = ($v -shr 2) -band 3
    $boost    = $v -band 3
    $i = switch ($interval) { 1 { T 'psLong' } 2 { T 'psShort' } default { T 'psAuto' } }
    $l = switch ($length)   { 1 { T 'psVariable' } 2 { T 'psFixed' } default { T 'psAuto' } }
    $b = switch ($boost)    { 0 { '1:1' } 1 { '2:1' } default { '3:1' } }
    return ("0x{0:X2} ({0})  ·  {1}: {2}  ·  {3}: {4}  ·  {5}: {6}" -f $v, (T 'psInterval'), $i, (T 'psQuantum'), $l, (T 'psBoost'), $b)
}

function Get-PsSelected {
    $item = $cmbPsPreset.SelectedItem
    if ($null -eq $item) { return $null }
    $tag = [int]$item.Tag
    if ($tag -ge 0) { return $tag }
    $raw = ([string]$txtPsCustom.Text).Trim() -replace '^0x', ''
    if ($raw -notmatch '^[0-9A-Fa-f]{1,2}$') { return $null }
    $n = [Convert]::ToInt32($raw, 16)
    if ($n -gt 0x3F) { return $null }
    return $n
}

function Update-PsView {
    $cur = Get-RegOrNull $script:PsPath 'Win32PrioritySeparation'
    if ($null -ne $cur) { $txtPsCurrent.Text = Format-PrioritySeparation ([int]$cur) }
    $isCustom = ($null -ne $cmbPsPreset.SelectedItem -and [int]$cmbPsPreset.SelectedItem.Tag -lt 0)
    $txtPsCustom.IsEnabled = $isCustom
    $sel = Get-PsSelected
    $txtPsDecoded.Text = if ($null -ne $sel) { Format-PrioritySeparation $sel } else { T 'psInvalid' }
}

$cmbPsPreset.Add_SelectionChanged({ Update-PsView })
$txtPsCustom.Add_TextChanged({ Update-PsView })
$btnPsApply.Add_Click({
    $v = Get-PsSelected
    if ($null -eq $v) { Write-Log "[AVVISO] $(T 'psInvalid')"; return }
    Set-Reg $script:PsPath 'Win32PrioritySeparation' $v 'DWord' ("Win32PrioritySeparation = 0x{0:X2}" -f $v) | Out-Null
    Update-PsView
})
$btnPsDefault.Add_Click({
    Set-Reg $script:PsPath 'Win32PrioritySeparation' 2 'DWord' 'Win32PrioritySeparation = 0x02 (predefinito)' | Out-Null
    $cmbPsPreset.SelectedIndex = 0
    Update-PsView
})

# ------------------------------------------------------------------------------
# 26. MULTIMEDIA CLASS SCHEDULER (MMCSS)
# ------------------------------------------------------------------------------
# Lo stesso pannello del «Multimedia Scheduler Configuration Tool»: due valori
# generali e le variabili di ogni attivita' (Games, Audio, Pro Audio...).
# Il servizio legge i valori all'avvio: le modifiche valgono dopo un riavvio.
$script:MmRoot = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
$cmbMmNet = E 'cmbMmNet'; $cmbMmResp = E 'cmbMmResp'; $cmbMmTask = E 'cmbMmTask'
$txtMmAffinity = E 'txtMmAffinity'; $txtMmClock = E 'txtMmClock'
$cmbMmGpu = E 'cmbMmGpu'; $cmbMmPrio = E 'cmbMmPrio'; $cmbMmSched = E 'cmbMmSched'; $cmbMmSfio = E 'cmbMmSfio'
$cmbMmBgOnly = E 'cmbMmBgOnly'; $cmbMmBgPrio = E 'cmbMmBgPrio'; $cmbMmLatency = E 'cmbMmLatency'
$btnMmApply = E 'btnMmApply'; $btnMmDefault = E 'btnMmDefault'; $btnMmBackup = E 'btnMmBackup'; $btnMmReload = E 'btnMmReload'

# Valori di fabbrica di Windows per le attivita' standard.
$script:MmDefaults = @{
    'Games'          = @{ Prio = 2; Sched = 'Medium'; Bg = 'False' }
    'Audio'          = @{ Prio = 6; Sched = 'Medium'; Bg = 'True'  }
    'Pro Audio'      = @{ Prio = 1; Sched = 'High';   Bg = 'False' }
    'Capture'        = @{ Prio = 5; Sched = 'Medium'; Bg = 'False' }
    'Distribution'   = @{ Prio = 4; Sched = 'Medium'; Bg = 'True'  }
    'Playback'       = @{ Prio = 3; Sched = 'Medium'; Bg = 'False' }
    'Window Manager' = @{ Prio = 5; Sched = 'Medium'; Bg = 'True'  }
}

function Add-ComboValues($combo, $values) {
    $combo.Items.Clear()
    foreach ($v in $values) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $it.Content = [string]$v; $it.Tag = $v
        [void]$combo.Items.Add($it)
    }
}
function Select-ComboValue($combo, $value) {
    foreach ($it in $combo.Items) {
        if ([string]$it.Tag -eq [string]$value) { $combo.SelectedItem = $it; return }
    }
    $combo.SelectedIndex = 0
}
function Get-ComboValue($combo) { if ($null -eq $combo.SelectedItem) { return $null }; return $combo.SelectedItem.Tag }

Add-ComboValues $cmbMmGpu (0..31)
Add-ComboValues $cmbMmPrio (1..8)
Add-ComboValues $cmbMmSched @('High','Medium','Low')
Add-ComboValues $cmbMmSfio @('High','Normal','Low','Idle')
Add-ComboValues $cmbMmBgOnly @('True','False')
Add-ComboValues $cmbMmBgPrio @('-','1','2','3','4','5','6','7','8')
Add-ComboValues $cmbMmLatency @('-','True','False')

function Read-MmTask {
    $name = Get-ComboValue $cmbMmTask
    if (-not $name) { return }
    $p = "$script:MmRoot\Tasks\$name"
    $aff = Get-RegOrNull $p 'Affinity'
    $txtMmAffinity.Text = if ($null -eq $aff) { '0' } else { '{0:X}' -f [uint32]([int64]$aff -band 0xFFFFFFFF) }
    $clk = Get-RegOrNull $p 'Clock Rate'
    $txtMmClock.Text = if ($null -eq $clk) { '10000' } else { [string]$clk }
    Select-ComboValue $cmbMmGpu  ($(if ($null -ne ($v = Get-RegOrNull $p 'GPU Priority')) { $v } else { 8 }))
    Select-ComboValue $cmbMmPrio ($(if ($null -ne ($v = Get-RegOrNull $p 'Priority')) { $v } else { 2 }))
    Select-ComboValue $cmbMmSched ($(if ($v = Get-RegOrNull $p 'Scheduling Category') { $v } else { 'Medium' }))
    Select-ComboValue $cmbMmSfio  ($(if ($v = Get-RegOrNull $p 'SFIO Priority') { $v } else { 'Normal' }))
    Select-ComboValue $cmbMmBgOnly ($(if ($v = Get-RegOrNull $p 'Background Only') { $v } else { 'False' }))
    Select-ComboValue $cmbMmBgPrio ($(if ($null -ne ($v = Get-RegOrNull $p 'Background Priority')) { $v } else { '-' }))
    Select-ComboValue $cmbMmLatency ($(if ($v = Get-RegOrNull $p 'Latency Sensitive') { $v } else { '-' }))
}

function Read-Mmcss {
    $keep = Get-ComboValue $cmbMmTask
    $tasks = @(Get-ChildItem "$script:MmRoot\Tasks" -ErrorAction SilentlyContinue | ForEach-Object { $_.PSChildName } | Sort-Object)
    Add-ComboValues $cmbMmTask $tasks
    if ($keep -and $tasks -contains $keep) { Select-ComboValue $cmbMmTask $keep }
    elseif ($tasks -contains 'Games') { Select-ComboValue $cmbMmTask 'Games' }
    else { $cmbMmTask.SelectedIndex = 0 }

    $net = Get-RegOrNull $script:MmRoot 'NetworkThrottlingIndex'
    if ($null -eq $net) { $net = 10 }
    if ([int64]$net -eq -1 -or [int64]$net -eq 4294967295) { $net = -1 }
    Select-ComboValue $cmbMmNet $net
    $resp = Get-RegOrNull $script:MmRoot 'SystemResponsiveness'
    if ($null -eq $resp) { $resp = 20 }
    Select-ComboValue $cmbMmResp $resp
    Read-MmTask
}

# Voci dei due menu generali: il testo resta leggibile, il Tag porta il valore.
function Set-MmGlobalItems {
    $cmbMmNet.Items.Clear()
    foreach ($pair in @(@(-1, (T 'mmNetOff')), @(10, (T 'mmNetDefault')), @(20, '20'), @(40, '40'), @(70, '70'))) {
        $it = New-Object System.Windows.Controls.ComboBoxItem; $it.Tag = $pair[0]; $it.Content = $pair[1]
        [void]$cmbMmNet.Items.Add($it)
    }
    $cmbMmResp.Items.Clear()
    foreach ($n in 0..10) {
        $v = $n * 10
        $it = New-Object System.Windows.Controls.ComboBoxItem; $it.Tag = $v
        $it.Content = if ($v -eq 20) { "20% ($(T 'mmDefaultWord'))" } else { "$v%" }
        [void]$cmbMmResp.Items.Add($it)
    }
}

$cmbMmTask.Add_SelectionChanged({ Read-MmTask })
$btnMmReload.Add_Click({ Read-Mmcss })

$btnMmBackup.Add_Click({
    $file = Join-Path ([Environment]::GetFolderPath('Desktop')) ("MMCSS_backup_{0}.reg" -f (Get-Date -Format 'yyyyMMdd_HHmm'))
    $p = Start-Process -FilePath "$env:SystemRoot\System32\reg.exe" -WindowStyle Hidden -Wait -PassThru `
        -ArgumentList @('export', '"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"', "`"$file`"", '/y')
    if ($p.ExitCode -eq 0) { Write-Log "[OK] Backup MMCSS salvato: $file" }
    else { Write-Log "[ERRORE] Backup MMCSS non riuscito (codice $($p.ExitCode))." }
})

$btnMmApply.Add_Click({
    $name = Get-ComboValue $cmbMmTask
    $clock = 0; $aff = 0
    if (-not [int]::TryParse(([string]$txtMmClock.Text).Trim(), [ref]$clock) -or $clock -lt 1000 -or $clock -gt 100000) {
        Write-Log "[AVVISO] $(T 'mmBadClock')"; return
    }
    $affRaw = ([string]$txtMmAffinity.Text).Trim() -replace '^0x', ''
    if ($affRaw -notmatch '^[0-9A-Fa-f]{1,8}$') { Write-Log "[AVVISO] $(T 'mmBadAffinity')"; return }
    $aff = [Convert]::ToInt64($affRaw, 16)
    if ($aff -gt [int]::MaxValue) { $aff = $aff - 4294967296 }

    Set-Reg $script:MmRoot 'NetworkThrottlingIndex' ([int](Get-ComboValue $cmbMmNet)) 'DWord' 'MMCSS / NetworkThrottlingIndex' | Out-Null
    Set-Reg $script:MmRoot 'SystemResponsiveness' ([int](Get-ComboValue $cmbMmResp)) 'DWord' 'MMCSS / SystemResponsiveness' | Out-Null
    if ($name) {
        $p = "$script:MmRoot\Tasks\$name"
        Set-Reg $p 'Affinity' ([int]$aff) 'DWord' "$name / Affinity" | Out-Null
        Set-Reg $p 'Clock Rate' $clock 'DWord' "$name / Clock Rate" | Out-Null
        Set-Reg $p 'GPU Priority' ([int](Get-ComboValue $cmbMmGpu)) 'DWord' "$name / GPU Priority" | Out-Null
        Set-Reg $p 'Priority' ([int](Get-ComboValue $cmbMmPrio)) 'DWord' "$name / Priority" | Out-Null
        Set-Reg $p 'Scheduling Category' ([string](Get-ComboValue $cmbMmSched)) 'String' "$name / Scheduling Category" | Out-Null
        Set-Reg $p 'SFIO Priority' ([string](Get-ComboValue $cmbMmSfio)) 'String' "$name / SFIO Priority" | Out-Null
        Set-Reg $p 'Background Only' ([string](Get-ComboValue $cmbMmBgOnly)) 'String' "$name / Background Only" | Out-Null
        $bp = [string](Get-ComboValue $cmbMmBgPrio)
        if ($bp -eq '-') { if ($null -ne (Get-RegOrNull $p 'Background Priority')) { Remove-Reg $p 'Background Priority' "$name / Background Priority" } }
        else { Set-Reg $p 'Background Priority' ([int]$bp) 'DWord' "$name / Background Priority" | Out-Null }
        $ls = [string](Get-ComboValue $cmbMmLatency)
        if ($ls -eq '-') { if ($null -ne (Get-RegOrNull $p 'Latency Sensitive')) { Remove-Reg $p 'Latency Sensitive' "$name / Latency Sensitive" } }
        else { Set-Reg $p 'Latency Sensitive' $ls 'String' "$name / Latency Sensitive" | Out-Null }
    }
    Write-Log "[INFO] $(T 'mmReboot')"
})

$btnMmDefault.Add_Click({
    $name = Get-ComboValue $cmbMmTask
    Select-ComboValue $cmbMmNet 10
    Select-ComboValue $cmbMmResp 20
    $txtMmAffinity.Text = '0'; $txtMmClock.Text = '10000'
    Select-ComboValue $cmbMmGpu 8
    Select-ComboValue $cmbMmSfio 'Normal'
    Select-ComboValue $cmbMmBgPrio '-'
    Select-ComboValue $cmbMmLatency '-'
    $d = $script:MmDefaults[[string]$name]
    if ($d) {
        Select-ComboValue $cmbMmPrio $d.Prio; Select-ComboValue $cmbMmSched $d.Sched; Select-ComboValue $cmbMmBgOnly $d.Bg
        Write-Log "[INFO] $(T 'mmDefaultsLoaded')"
    } else {
        Write-Log "[AVVISO] $(T 'mmNoDefaults')"
    }
})

# Stato iniziale delle pagine a effetto immediato.
function Initialize-LivePages {
    Set-MmGlobalItems
    Read-Mmcss
    Read-ShutdownMenu
    $cur = Get-RegOrNull $script:PsPath 'Win32PrioritySeparation'
    $match = $null
    foreach ($it in $cmbPsPreset.Items) { if ($null -ne $cur -and [int]$it.Tag -eq [int]$cur) { $match = $it } }
    if ($match) { $cmbPsPreset.SelectedItem = $match }
    else {
        $cmbPsPreset.SelectedIndex = $cmbPsPreset.Items.Count - 1
        if ($null -ne $cur) { $txtPsCustom.Text = '{0:X2}' -f [int]$cur }
    }
    Update-PsView
}
Initialize-LivePages

# ------------------------------------------------------------------------------
# 28. PAGINE A INTERRUTTORE: lettura, scrittura e disegno del catalogo
# ------------------------------------------------------------------------------
# Ogni voce del catalogo mostra lo stato reale del sistema e lo cambia appena
# la tocchi, come negli strumenti di privacy dedicati: niente coda, niente
# «Applica». Le pagine si costruiscono alla prima apertura, per non rallentare
# l'avvio con centinaia di controlli che magari non guarderai.

Add-Type -Namespace TweakAndrew -Name PowerApi -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("powrprof.dll")]
public static extern uint PowerGetActiveScheme(System.IntPtr root, out System.IntPtr scheme);
[System.Runtime.InteropServices.DllImport("powrprof.dll")]
public static extern uint PowerReadACValueIndex(System.IntPtr root, ref System.Guid scheme, ref System.Guid sub, ref System.Guid setting, out uint value);
[System.Runtime.InteropServices.DllImport("powrprof.dll")]
public static extern uint PowerWriteACValueIndex(System.IntPtr root, ref System.Guid scheme, ref System.Guid sub, ref System.Guid setting, uint value);
[System.Runtime.InteropServices.DllImport("powrprof.dll")]
public static extern uint PowerWriteDCValueIndex(System.IntPtr root, ref System.Guid scheme, ref System.Guid sub, ref System.Guid setting, uint value);
[System.Runtime.InteropServices.DllImport("powrprof.dll")]
public static extern uint PowerSetActiveScheme(System.IntPtr root, ref System.Guid scheme);
[System.Runtime.InteropServices.DllImport("kernel32.dll")]
public static extern System.IntPtr LocalFree(System.IntPtr mem);
'@ -ErrorAction SilentlyContinue

$script:CatById = @{}
foreach ($it in $script:Catalog) { $script:CatById[$it.Id] = $it }
$script:CatRows = New-Object System.Collections.ArrayList
$script:CatBuilt = @{}
$script:CatLoading = $false
$script:CatScope = 'U'

function Get-CatText([string]$key) {
    $t = Get-Text $script:CatText[$key]
    if ($t) { return $t }
    return $key
}

# --- registro, via .NET: piu' veloce del provider e senza problemi con «*» ---
function Get-CatKey([string]$path, [bool]$write) {
    $i = $path.IndexOf('\')
    $root = $path.Substring(0, $i); $sub = $path.Substring($i + 1)
    $hive = if ($root -eq 'HKCU') { [Microsoft.Win32.RegistryHive]::CurrentUser } else { [Microsoft.Win32.RegistryHive]::LocalMachine }
    if ($root -eq 'HKCR') { $sub = 'SOFTWARE\Classes\' + $sub }
    $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey($hive, [Microsoft.Win32.RegistryView]::Registry64)
    if ($write) { return @{ Base = $base; Sub = $sub; Key = $base.CreateSubKey($sub) } }
    return @{ Base = $base; Sub = $sub; Key = $base.OpenSubKey($sub) }
}

function Get-CatRaw([string]$path, [string]$name) {
    $k = Get-CatKey $path $false
    if ($null -eq $k.Key) { return $null }
    try {
        $v = $k.Key.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
        # Un byte[] restituito cosi' com'e' verrebbe srotolato da PowerShell: la virgola lo tiene intero.
        if ($v -is [array]) { return ,$v }
        return $v
    } finally { $k.Key.Close() }
}

function ConvertTo-CatBytes([string]$hex) {
    return ,[byte[]]@($hex.Trim() -split '\s+' | Where-Object { $_ } | ForEach-Object { [Convert]::ToByte($_, 16) })
}

function Get-CatKv([string]$s, [string]$name) {
    if (-not $s) { return $null }
    foreach ($part in $s.Split(';')) {
        $kv = $part.Split('=', 2)
        if ($kv.Count -eq 2 -and $kv[0] -eq $name) { return $kv[1] }
    }
    return $null
}

# Vero se il valore attuale corrisponde a una delle alternative della specifica.
function Test-CatValue($op, [string]$spec) {
    $path = $op[0]; $name = $op[1]; $type = $op[2]
    foreach ($alt in $spec.Split(',')) {
        if ($type -eq 'Key') {
            $k = Get-CatKey $path $false
            $exists = $null -ne $k.Key
            if ($exists) { $k.Key.Close() }
            if (($alt -eq '+') -eq $exists) { return $true }
            continue
        }
        $raw = Get-CatRaw $path $name
        if ($type -like 'Kv:*') {
            $v = Get-CatKv ([string]$raw) $type.Substring(3)
            if ($alt -eq '-') { if ($null -eq $v) { return $true } } elseif ($v -eq $alt) { return $true }
            continue
        }
        if ($alt -eq '-') { if ($null -eq $raw) { return $true }; continue }
        if ($null -eq $raw) { continue }
        switch -Wildcard ($type) {
            'D' { try { if (([int64]$raw -band 4294967295L) -eq ([int64]$alt -band 4294967295L)) { return $true } } catch {} }
            'Q' { try { if ([int64]$raw -eq [int64]$alt) { return $true } } catch {} }
            'B' { if ($raw -is [byte[]] -and [BitConverter]::ToString($raw) -eq [BitConverter]::ToString((ConvertTo-CatBytes $alt))) { return $true } }
            'Byte:*' {
                $n = [int]$type.Split(':')[1]
                if ($raw -is [byte[]] -and $raw.Length -gt $n -and $raw[$n] -eq [int]$alt) { return $true }
            }
            'Bit:*' {
                $p = $type.Split(':'); $n = [int]$p[1]; $mask = [Convert]::ToInt32($p[2], 16)
                if ($raw -is [byte[]] -and $raw.Length -gt $n) {
                    $set = ($raw[$n] -band $mask) -ne 0
                    if ($set -eq ($alt -eq '1')) { return $true }
                }
            }
            default {
                $want = if ($alt -eq '""') { '' } else { $alt }
                if ([string]$raw -eq $want) { return $true }
            }
        }
    }
    return $false
}

# Scrive la prima alternativa della specifica.
function Set-CatValue($op, [string]$spec) {
    $path = $op[0]; $name = $op[1]; $type = $op[2]
    $val = $spec.Split(',')[0]
    if ($type -eq 'Key') {
        if ($val -eq '+') { $k = Get-CatKey $path $true; if ($k.Key) { $k.Key.Close() } }
        else {
            $k = Get-CatKey $path $false
            if ($null -ne $k.Key) { $k.Key.Close(); $k.Base.DeleteSubKeyTree($k.Sub, $false) }
        }
        return
    }
    if ($type -like 'Kv:*') {
        $pair = $type.Substring(3)
        $raw = [string](Get-CatRaw $path $name)
        $parts = @($raw.Split(';') | Where-Object { $_ -and -not $_.StartsWith("$pair=") })
        if ($val -ne '-') { $parts += "$pair=$val" }
        $k = Get-CatKey $path $true
        try { $k.Key.SetValue($name, (($parts -join ';') + ';'), [Microsoft.Win32.RegistryValueKind]::String) } finally { $k.Key.Close() }
        return
    }
    if ($val -eq '-') {
        $k = Get-CatKey $path $false
        if ($null -ne $k.Key) {
            $k.Key.Close()
            $k = Get-CatKey $path $true
            try { $k.Key.DeleteValue($name, $false) } finally { $k.Key.Close() }
        }
        return
    }
    if ($type -like 'Byte:*' -or $type -like 'Bit:*') {
        $raw = Get-CatRaw $path $name
        if (-not ($raw -is [byte[]])) { throw "valore binario assente" }
        $p = $type.Split(':'); $n = [int]$p[1]
        if ($type -like 'Byte:*') { $raw[$n] = [byte][int]$val }
        else {
            $mask = [Convert]::ToInt32($p[2], 16)
            if ($val -eq '1') { $raw[$n] = [byte]($raw[$n] -bor $mask) } else { $raw[$n] = [byte]($raw[$n] -band (-bnot $mask) -band 0xFF) }
        }
        $k = Get-CatKey $path $true
        try { $k.Key.SetValue($name, [byte[]]$raw, [Microsoft.Win32.RegistryValueKind]::Binary) } finally { $k.Key.Close() }
        return
    }
    $k = Get-CatKey $path $true
    try {
        switch ($type) {
            'D' {
                # Valori negativi o oltre 2^31 (es. -1 = FFFFFFFF) vanno passati come int32 con gli stessi bit.
                $u = [uint32]([int64]$val -band 4294967295L)
                $k.Key.SetValue($name, [BitConverter]::ToInt32([BitConverter]::GetBytes($u), 0), [Microsoft.Win32.RegistryValueKind]::DWord)
            }
            'Q' { $k.Key.SetValue($name, [int64]$val, [Microsoft.Win32.RegistryValueKind]::QWord) }
            'B' { $k.Key.SetValue($name, [byte[]](ConvertTo-CatBytes $val), [Microsoft.Win32.RegistryValueKind]::Binary) }
            'E' { $k.Key.SetValue($name, $val, [Microsoft.Win32.RegistryValueKind]::ExpandString) }
            default {
                $s = if ($val -eq '""') { '' } else { $val }
                $kind = if ($s -match '%\w+%') { [Microsoft.Win32.RegistryValueKind]::ExpandString } else { [Microsoft.Win32.RegistryValueKind]::String }
                $k.Key.SetValue($name, $s, $kind)
            }
        }
    } finally { $k.Key.Close() }
}

# --- servizi, attivita' pianificate, piano energetico ---
function Get-CatServiceMode([string]$svc) {
    $start = Get-CatRaw "HKLM\SYSTEM\CurrentControlSet\Services\$svc" 'Start'
    if ($null -eq $start) { return $null }
    switch ([int]$start) {
        2 { if ((Get-CatRaw "HKLM\SYSTEM\CurrentControlSet\Services\$svc" 'DelayedAutostart') -eq 1) { return 'AD' } else { return 'A' } }
        3 { return 'M' }
        4 { return 'X' }
        default { return 'A' }
    }
}

function Set-CatServiceMode([string]$svc, [string]$mode) {
    $arg = switch ($mode) { 'A' { 'auto' } 'AD' { 'delayed-auto' } 'M' { 'demand' } default { 'disabled' } }
    $out = & sc.exe config $svc start= $arg 2>&1
    if ($LASTEXITCODE -ne 0) {
        # Alcuni servizi protetti rifiutano sc.exe: si scrive il registro, vale dal riavvio.
        $n = switch ($mode) { 'M' { 3 } 'X' { 4 } default { 2 } }
        Set-CatValue @("HKLM\SYSTEM\CurrentControlSet\Services\$svc", 'Start', 'D') "$n"
        Set-CatValue @("HKLM\SYSTEM\CurrentControlSet\Services\$svc", 'DelayedAutostart', 'D') $(if ($mode -eq 'AD') { '1' } else { '-' })
    }
}

$script:TaskService = $null
function Get-CatTask([string]$full) {
    if ($null -eq $script:TaskService) {
        $script:TaskService = New-Object -ComObject Schedule.Service
        $script:TaskService.Connect()
    }
    $i = $full.LastIndexOf('\')
    $folder = if ($i -le 0) { '\' } else { $full.Substring(0, $i) }
    try { return $script:TaskService.GetFolder($folder).GetTask($full.Substring($i + 1)) } catch { return $null }
}

function Get-ActiveSchemeGuid {
    $ptr = [IntPtr]::Zero
    if ([TweakAndrew.PowerApi]::PowerGetActiveScheme([IntPtr]::Zero, [ref]$ptr) -ne 0) { return $null }
    try { return [System.Runtime.InteropServices.Marshal]::PtrToStructure($ptr, [type][guid]) }
    finally { [TweakAndrew.PowerApi]::LocalFree($ptr) | Out-Null }
}

function Get-CatPowerValue($it) {
    $scheme = Get-ActiveSchemeGuid
    if ($null -eq $scheme) { return $null }
    $sub = [guid]$it.Sub; $set = [guid]$it.Set; $v = [uint32]0
    if ([TweakAndrew.PowerApi]::PowerReadACValueIndex([IntPtr]::Zero, [ref]$scheme, [ref]$sub, [ref]$set, [ref]$v) -ne 0) { return $null }
    return [string]$v
}

function Set-CatPowerValue($it, [string]$value) {
    $scheme = Get-ActiveSchemeGuid
    $sub = [guid]$it.Sub; $set = [guid]$it.Set
    $r1 = [TweakAndrew.PowerApi]::PowerWriteACValueIndex([IntPtr]::Zero, [ref]$scheme, [ref]$sub, [ref]$set, [uint32]$value)
    $r2 = [TweakAndrew.PowerApi]::PowerWriteDCValueIndex([IntPtr]::Zero, [ref]$scheme, [ref]$sub, [ref]$set, [uint32]$value)
    [TweakAndrew.PowerApi]::PowerSetActiveScheme([IntPtr]::Zero, [ref]$scheme) | Out-Null
    if ($r1 -ne 0 -and $r2 -ne 0) { throw "powrprof ha restituito $r1" }
}

# --- stato di una voce: $true/$false per gli interruttori, la chiave per i menu ---
function Get-CatState($it) {
    switch ($it.Kind) {
        'T' {
            foreach ($op in $it.Ops) { if (-not (Test-CatValue $op $op[3])) { return $false } }
            return $true
        }
        'S' {
            foreach ($o in $it.Opts) {
                $ok = $true
                for ($i = 0; $i -lt $it.Ops.Count; $i++) { if (-not (Test-CatValue $it.Ops[$i] $o.Vals[$i])) { $ok = $false; break } }
                if ($ok) { return $o.Key }
            }
            return $null
        }
        'V' { return (Get-CatServiceMode $it.Svcs[0]) }
        'J' {
            $any = $false
            foreach ($t in $it.Tasks) { $task = Get-CatTask $t; if ($null -ne $task) { $any = $true; if (-not $task.Enabled) { return $false } } }
            if (-not $any) { return $null }
            return $true
        }
        'N' { return (Get-CatPowerValue $it) }
    }
}

# Porta la voce allo stato richiesto e scrive una riga nel registro operazioni.
function Set-CatState($it, $state) {
    $label = Get-Text $script:CatText[$it.Id]
    try {
        switch ($it.Kind) {
            'T' { foreach ($op in $it.Ops) { Set-CatValue $op $(if ($state) { $op[3] } else { $op[4] }) } }
            'S' {
                $o = $it.Opts | Where-Object { $_.Key -eq $state } | Select-Object -First 1
                for ($i = 0; $i -lt $it.Ops.Count; $i++) { Set-CatValue $it.Ops[$i] $o.Vals[$i] }
            }
            'V' { foreach ($s in $it.Svcs) { if ($null -ne (Get-CatServiceMode $s)) { Set-CatServiceMode $s $state } } }
            'J' { foreach ($t in $it.Tasks) { $task = Get-CatTask $t; if ($null -ne $task) { $task.Enabled = [bool]$state } } }
            'N' { Set-CatPowerValue $it ([string]$state) }
        }
        $shown = if ($state -is [bool]) { if ($state) { 'ON' } else { 'OFF' } } else { Get-CatText "$($it.Id)#$state" }
        Write-Log "[OK] $label - $shown"
        if ($it.Flags -match 'X') { $script:CatNeedsExplorer = $true }
        return $true
    } catch {
        Write-Log "[ERRORE] $label - $($_.Exception.Message)"
        return $false
    }
}

# --- disegno ---
function New-CatBrush([string]$hex) { return (New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($hex))) }

function Set-CatTooltip($el, $it, $page) {
    $text = Get-Text $script:CatTip[$it.Id]
    if (-not $text) { return }
    $tt = New-Object System.Windows.Controls.ToolTip
    $tt.Content = $text
    $pa = $page.TryFindResource('PA')
    if ($null -ne $pa) { $tt.Resources['PA'] = $pa }
    $el.ToolTip = $tt
    [System.Windows.Controls.ToolTipService]::SetInitialShowDelay($el, 450)
    [System.Windows.Controls.ToolTipService]::SetShowDuration($el, 30000)
}

function Update-CatRow($row) {
    $script:CatLoading = $true
    try {
        $state = Get-CatState $row.Item
        if ($row.Item.Kind -in @('T','J')) {
            if ($null -eq $state) { $row.Control.IsEnabled = $false; $row.Control.IsChecked = $false }
            else { $row.Control.IsChecked = [bool]$state }
        } else {
            $combo = $row.Control
            if ($null -eq $state) {
                if ($row.Item.Kind -eq 'V') { $combo.IsEnabled = $false; $combo.SelectedIndex = -1; return }
                # Nessuna opzione corrisponde ai valori attuali: si mostra «Personalizzato».
                $state = 'custom'
            }
            $match = $null
            foreach ($ci in $combo.Items) { if ([string]$ci.Tag -eq [string]$state) { $match = $ci } }
            if ($null -eq $match) {
                # Valore fuori dall'elenco: lo mostriamo com'e', senza toccarlo.
                $match = New-Object System.Windows.Controls.ComboBoxItem
                $match.Tag = [string]$state
                $match.Content = if ($state -eq 'custom') { T 'catCustom' } else { "$(T 'catCustom') ($state)" }
                [void]$combo.Items.Add($match)
            }
            $combo.SelectedItem = $match
        }
    } finally { $script:CatLoading = $false }
}

function Get-CatOptions($it) {
    if ($it.Kind -eq 'V') {
        return @(
            @{ Key = 'A';  Text = (T 'svcAuto') },
            @{ Key = 'AD'; Text = (T 'svcAutoDelayed') },
            @{ Key = 'M';  Text = (T 'svcManual') },
            @{ Key = 'X';  Text = (T 'svcDisabled') }
        )
    }
    return @($it.Opts | ForEach-Object { @{ Key = $_.Key; Text = (Get-CatText "$($it.Id)#$($_.Key)") } })
}

function New-CatRow($it, $page) {
    $grid = New-Object System.Windows.Controls.Grid
    $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = [System.Windows.GridLength]::Auto
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $grid.ColumnDefinitions.Add($c0); $grid.ColumnDefinitions.Add($c1)
    $label = Get-CatText $it.Id

    # Pallino del livello consigliato e sigla IA, solo nella privacy avanzata.
    if ($it.Page -eq 'priv') {
        $badges = New-Object System.Windows.Controls.StackPanel
        $badges.Orientation = 'Horizontal'; $badges.VerticalAlignment = 'Center'; $badges.Margin = '10,0,0,0'
        $dot = New-Object System.Windows.Shapes.Ellipse
        $dot.Width = 8; $dot.Height = 8
        $dot.Fill = New-CatBrush $(switch ($it.Rec) { 'y' { '#FF2ED3A7' } 'l' { '#FFE0A25E' } default { '#FFF87171' } })
        $dot.ToolTip = T $(switch ($it.Rec) { 'y' { 'recYes' } 'l' { 'recLimited' } default { 'recNo' } })
        [void]$badges.Children.Add($dot)
        $ai = New-Object System.Windows.Controls.Border
        $ai.Width = 22; $ai.Height = 15; $ai.CornerRadius = 4; $ai.Margin = '6,0,0,0'
        if ($it.Flags -match 'A') {
            $ai.Background = New-CatBrush '#2438BDF8'
            $t = New-Object System.Windows.Controls.TextBlock
            $t.Text = T 'aiTag'; $t.FontSize = 9.5; $t.FontWeight = 'Bold'; $t.Foreground = New-CatBrush '#FF7DD3FC'
            $t.HorizontalAlignment = 'Center'; $t.VerticalAlignment = 'Center'
            $ai.Child = $t
            $ai.ToolTip = T 'aiRelevant'
        }
        [void]$badges.Children.Add($ai)
        [System.Windows.Controls.Grid]::SetColumn($badges, 0)
        [void]$grid.Children.Add($badges)
    }

    if ($it.Kind -in @('T','J')) {
        $cb = New-Object System.Windows.Controls.CheckBox
        $cb.Content = $label
        $cb.Tag = $it.Id
        [System.Windows.Controls.Grid]::SetColumn($cb, 1)
        [void]$grid.Children.Add($cb)
        $ctl = $cb
        $handler = {
            if ($script:CatLoading) { return }
            $item = $script:CatById[[string]$this.Tag]
            [void](Set-CatState $item ($this.IsChecked -eq $true))
            $r = $script:CatRows | Where-Object { $_.Control -eq $this } | Select-Object -First 1
            if ($r) { Update-CatRow $r }
            Update-CatExplorerHint
        }
        $cb.Add_Checked($handler); $cb.Add_Unchecked($handler)
    } else {
        $inner = New-Object System.Windows.Controls.Grid
        $inner.Margin = '10,4,10,4'
        $ic0 = New-Object System.Windows.Controls.ColumnDefinition; $ic0.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
        $ic1 = New-Object System.Windows.Controls.ColumnDefinition; $ic1.Width = [System.Windows.GridLength]::Auto
        $inner.ColumnDefinitions.Add($ic0); $inner.ColumnDefinitions.Add($ic1)
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = $label; $tb.TextWrapping = 'Wrap'; $tb.VerticalAlignment = 'Center'; $tb.Margin = '0,0,12,0'
        $tb.Foreground = New-CatBrush '#FFC4C4CC'; $tb.FontSize = 12.5
        $tb.FontFamily = New-Object System.Windows.Media.FontFamily('Roboto, Segoe UI Variable Text, Segoe UI')
        [void]$inner.Children.Add($tb)
        $combo = New-Object System.Windows.Controls.ComboBox
        $combo.Width = 210; $combo.Tag = $it.Id; $combo.VerticalAlignment = 'Center'
        foreach ($o in (Get-CatOptions $it)) {
            $ci = New-Object System.Windows.Controls.ComboBoxItem
            $ci.Tag = $o.Key; $ci.Content = $o.Text
            [void]$combo.Items.Add($ci)
        }
        [System.Windows.Controls.Grid]::SetColumn($combo, 1)
        [void]$inner.Children.Add($combo)
        [System.Windows.Controls.Grid]::SetColumn($inner, 1)
        [void]$grid.Children.Add($inner)
        $ctl = $combo
        $combo.Add_SelectionChanged({
            if ($script:CatLoading) { return }
            $sel = $this.SelectedItem
            if ($null -eq $sel -or [string]$sel.Content -like "$(T 'catCustom')*") { return }
            $item = $script:CatById[[string]$this.Tag]
            [void](Set-CatState $item ([string]$sel.Tag))
            $r = $script:CatRows | Where-Object { $_.Control -eq $this } | Select-Object -First 1
            if ($r) { Update-CatRow $r }
            Update-CatExplorerHint
        })
        $tb.Tag = 'label'
    }
    Set-CatTooltip $grid $it $page
    $row = [pscustomobject]@{ Item = $it; Control = $ctl; Element = $grid; Label = $label; Card = $null }
    [void]$script:CatRows.Add($row)
    Update-CatRow $row
    return $row
}

function New-CatCard([string]$title) {
    $card = New-Object System.Windows.Controls.Border
    $card.Style = $window.FindResource('Glass')
    $sp = New-Object System.Windows.Controls.StackPanel
    $h = New-Object System.Windows.Controls.TextBlock
    $h.Text = $title.ToUpper(); $h.Style = $window.FindResource('CardTitle')
    [void]$sp.Children.Add($h)
    $card.Child = $sp
    return @{ Card = $card; Panel = $sp }
}

function New-CatButton([string]$text, [string]$dot) {
    $b = New-Object System.Windows.Controls.Button
    $b.Style = $window.FindResource('DotBtn')
    $b.Margin = '0,0,8,8'
    $b.Content = $text
    if ($dot) { $b.Tag = New-CatBrush $dot }
    return $b
}

# Applica lo stesso stato a molte voci, con una sola conferma.
function Invoke-CatBulk([string]$page, [scriptblock]$pick, [string]$question) {
    if (-not (Show-Dialog -Title (T 'catBulkTitle') -Message $question -Kind 'warn')) { return }
    $script:OkCount = 0; $script:WarnCount = 0; $script:SkipCount = 0
    $rows = @($script:CatRows | Where-Object { $_.Item.Page -eq $page })
    $n = 0
    foreach ($r in $rows) {
        $n++
        $target = & $pick $r.Item
        if ($null -eq $target) { continue }
        $now = Get-CatState $r.Item
        if ($null -eq $now) { continue }
        if ([string]$now -eq [string]$target) { $script:SkipCount++; continue }
        Update-Progress -Current $n -Total $rows.Count -Label (Get-CatText $r.Item.Id)
        [void](Set-CatState $r.Item $target)
    }
    foreach ($r in $rows) { Update-CatRow $r }
    Update-Progress -Current $rows.Count -Total $rows.Count -Label ''
    Show-RunSummary
    Update-CatExplorerHint
}

function Get-CatRecTarget($it) {
    if ($it.Rec -eq '-' -or [string]::IsNullOrEmpty($it.Rec)) { return $null }
    if ($it.Kind -in @('T','J')) { return ($it.Rec -eq '1') }
    return $it.Rec
}
function Get-CatDefTarget($it) {
    if ($it.Kind -in @('T','J')) { return ($it.Def -eq '1') }
    if ($it.Page -eq 'priv') { return ($it.Def -eq '1') }
    return $it.Def
}

$script:CatNeedsExplorer = $false
$script:CatExplorerButtons = @()
function Update-CatExplorerHint {
    foreach ($b in $script:CatExplorerButtons) {
        $b.Tag = if ($script:CatNeedsExplorer) { New-CatBrush '#FFFFB86B' } else { $null }
    }
}

function Restart-Explorer {
    Get-Process -Name explorer -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    Start-Sleep -Milliseconds 700
    if (-not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) { Start-Process explorer.exe }
    $script:CatNeedsExplorer = $false
    Write-Log "[OK] Esplora risorse riavviato."
}

function Update-CatFilter([string]$page) {
    $box = $script:CatSearch[$page]
    $q = if ($box) { $box.Text.Trim() } else { '' }
    foreach ($card in $script:CatCards[$page]) {
        $visible = 0
        foreach ($r in $card.Rows) {
            $ok = (-not $q) -or ($r.Label -like "*$q*")
            if ($page -eq 'priv' -and $script:CatScope -ne 'all') { $ok = $ok -and ($r.Item.Flags -match $script:CatScope) }
            $r.Element.Visibility = if ($ok) { 'Visible' } else { 'Collapsed' }
            if ($ok) { $visible++ }
        }
        $card.Card.Visibility = if ($visible -gt 0) { 'Visible' } else { 'Collapsed' }
    }
}

$script:CatSearch = @{}
$script:CatCards = @{}

# Costruisce una pagina del catalogo dentro il contenitore indicato.
function Initialize-CatPage([string]$page, $hostEl, [bool]$embedded = $false) {
    if ($null -eq $hostEl) { return }
    $old = @($script:CatRows | Where-Object { $_.Item.Page -eq $page })
    foreach ($o in $old) { $script:CatRows.Remove($o) }
    $hostEl.Children.Clear()
    $script:CatCards[$page] = @()

    $root = New-Object System.Windows.Controls.Grid
    $r0 = New-Object System.Windows.Controls.RowDefinition; $r0.Height = [System.Windows.GridLength]::Auto
    $r1 = New-Object System.Windows.Controls.RowDefinition; $r1.Height = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $root.RowDefinitions.Add($r0); $root.RowDefinitions.Add($r1)

    # Barra degli strumenti: ricerca e azioni sull'intera pagina.
    $bar = New-Object System.Windows.Controls.WrapPanel
    $bar.Margin = '7,0,7,6'
    $search = New-Object System.Windows.Controls.TextBox
    $search.Width = 240; $search.Height = 34; $search.Margin = '0,0,12,8'; $search.Padding = '10,0'
    $search.VerticalContentAlignment = 'Center'
    $search.Tag = $page
    $hint = New-Object System.Windows.Controls.TextBlock
    $hint.Text = T 'catSearch'; $hint.Foreground = New-CatBrush '#FF6E6E78'; $hint.IsHitTestVisible = $false
    $hint.Margin = '12,0,0,0'; $hint.VerticalAlignment = 'Center'
    $sgrid = New-Object System.Windows.Controls.Grid
    $sgrid.Margin = '0,0,12,8'
    $search.Margin = '0'
    [void]$sgrid.Children.Add($search); [void]$sgrid.Children.Add($hint)
    $search.Add_TextChanged({
        $p = [string]$this.Tag
        $h = ($this.Parent.Children | Where-Object { $_ -is [System.Windows.Controls.TextBlock] } | Select-Object -First 1)
        if ($h) { $h.Visibility = if ($this.Text) { 'Collapsed' } else { 'Visible' } }
        Update-CatFilter $p
    })
    $script:CatSearch[$page] = $search
    if (-not $embedded) { [void]$bar.Children.Add($sgrid) }

    if ($page -eq 'priv') {
        foreach ($s in @(@{ K = 'U'; T = 'scopeUser' }, @{ K = 'M'; T = 'scopeMachine' }, @{ K = 'all'; T = 'scopeAll' })) {
            $rb = New-Object System.Windows.Controls.RadioButton
            $rb.Content = T $s.T; $rb.GroupName = 'CatScope'; $rb.Tag = $s.K
            $rb.Margin = '0,6,4,8'; $rb.VerticalAlignment = 'Center'
            if ($script:CatScope -eq $s.K) { $rb.IsChecked = $true }
            $rb.Add_Checked({ $script:CatScope = [string]$this.Tag; Update-CatFilter 'priv' })
            [void]$bar.Children.Add($rb)
        }
        $bar2 = New-Object System.Windows.Controls.WrapPanel
        $bar2.Margin = '7,0,7,6'
        $b1 = New-CatButton (T 'applyRecYes') '#FF2ED3A7'
        $b1.Add_Click({ Invoke-CatBulk 'priv' { param($i) if ($i.Rec -eq 'y') { $true } else { $null } } (T 'askRecYes') })
        $b2 = New-CatButton (T 'applyRecLimited') '#FFE0A25E'
        $b2.Add_Click({ Invoke-CatBulk 'priv' { param($i) if ($i.Rec -in @('y','l')) { $true } else { $null } } (T 'askRecLimited') })
        $b3 = New-CatButton (T 'applyRecAll') '#FFF87171'
        $b3.Add_Click({ Invoke-CatBulk 'priv' { param($i) $true } (T 'askRecAll') })
        $b4 = New-CatButton (T 'undoAllFactory') ''
        $b4.Add_Click({ Invoke-CatBulk 'priv' { param($i) Get-CatDefTarget $i } (T 'askFactory') })
        $b5 = New-CatButton (T 'makeRestorePoint') ''
        $b5.Add_Click({ New-TweakRestorePoint })
        foreach ($b in @($b1, $b2, $b3, $b4, $b5)) { [void]$bar2.Children.Add($b) }
        $legend = New-Object System.Windows.Controls.TextBlock
        $legend.Text = T 'privLegend'; $legend.Style = $window.FindResource('SubTitle'); $legend.Margin = '7,0,7,8'; $legend.TextWrapping = 'Wrap'
        $top = New-Object System.Windows.Controls.StackPanel
        [void]$top.Children.Add($bar); [void]$top.Children.Add($bar2); [void]$top.Children.Add($legend)
        [System.Windows.Controls.Grid]::SetRow($top, 0)
        [void]$root.Children.Add($top)
    } else {
        $bRec = New-CatButton (T 'applyRecommended') '#FF2ED3A7'
        $bRec.DataContext = $page
        $bRec.Add_Click({ $p = [string]$this.DataContext; Invoke-CatBulk $p { param($i) Get-CatRecTarget $i } (T 'askRecommended') })
        $bDef = New-CatButton (T 'restoreWindows') ''
        $bDef.DataContext = $page
        $bDef.Add_Click({ $p = [string]$this.DataContext; Invoke-CatBulk $p { param($i) Get-CatDefTarget $i } (T 'askWindowsDefaults') })
        [void]$bar.Children.Add($bRec); [void]$bar.Children.Add($bDef)
        if (@($script:Catalog | Where-Object { $_.Page -eq $page -and $_.Flags -match 'X' }).Count -gt 0) {
            $bEx = New-CatButton (T 'restartExplorer') ''
            $bEx.Add_Click({ Restart-Explorer; Update-CatExplorerHint })
            $script:CatExplorerButtons += $bEx
            [void]$bar.Children.Add($bEx)
        }
        [System.Windows.Controls.Grid]::SetRow($bar, 0)
        [void]$root.Children.Add($bar)
    }

    # Due colonne di schede, riempite tenendo le altezze il piu' possibile pari.
    $cols = New-Object System.Windows.Controls.Grid
    foreach ($i in 0..1) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
        $cols.ColumnDefinitions.Add($cd)
    }
    $stacks = @((New-Object System.Windows.Controls.StackPanel), (New-Object System.Windows.Controls.StackPanel))
    $heights = @(0, 0)
    for ($i = 0; $i -lt 2; $i++) { [System.Windows.Controls.Grid]::SetColumn($stacks[$i], $i); [void]$cols.Children.Add($stacks[$i]) }

    $items = @($script:Catalog | Where-Object { $_.Page -eq $page })
    $groups = @($items | ForEach-Object { $_.Group } | Select-Object -Unique)
    foreach ($g in $groups) {
        $gi = @($items | Where-Object { $_.Group -eq $g })
        $c = New-CatCard (Get-CatText "g.$page.$g")
        $rows = @()
        foreach ($it in $gi) {
            $row = New-CatRow $it $hostEl
            [void]$c.Panel.Children.Add($row.Element)
            $rows += $row
        }
        $col = if ($heights[0] -le $heights[1]) { 0 } else { 1 }
        [void]$stacks[$col].Children.Add($c.Card)
        $heights[$col] += $gi.Count + 2
        $script:CatCards[$page] += @{ Card = $c.Card; Rows = $rows }
    }

    if ($embedded) {
        [System.Windows.Controls.Grid]::SetRow($cols, 1)
        [void]$root.Children.Add($cols)
    } else {
        $sv = New-Object System.Windows.Controls.ScrollViewer
        $sv.VerticalScrollBarVisibility = 'Auto'; $sv.Padding = '0,0,6,0'
        $sv.Content = $cols
        [System.Windows.Controls.Grid]::SetRow($sv, 1)
        [void]$root.Children.Add($sv)
    }
    [void]$hostEl.Children.Add($root)
    $script:CatBuilt[$page] = $script:LangCode
    Update-CatFilter $page
}

function New-TweakRestorePoint {
    try {
        Enable-ComputerRestore -Drive "$env:SystemDrive\" -ErrorAction SilentlyContinue
        # Windows accetta un punto ogni 24 ore: per crearne uno adesso si toglie il limite.
        Set-CatValue @('HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore', 'SystemRestorePointCreationFrequency', 'D') '0'
        Checkpoint-Computer -Description 'Tweak Andrew' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
        Write-Log "[OK] Punto di ripristino creato."
        $txtProgressLabel.Text = T 'restoreDone'
    } catch {
        Write-Log "[ERRORE] Punto di ripristino - $($_.Exception.Message)"
        $txtProgressLabel.Text = T 'restoreFail'
    }
}

# Pagine del catalogo e contenitori: la pagina si costruisce quando la apri.
$script:CatHosts = @{
    exp   = (E 'catExp')
    task  = (E 'catTask')
    notif = (E 'catNotif')
    game  = (E 'catGame')
    win   = (E 'catWin')
    priv  = (E 'catPriv')
    power = (E 'catPower')
}

function Show-CatPageIfNeeded([string]$page) {
    if (-not $script:CatHosts.ContainsKey($page)) { return }
    if ($script:CatBuilt[$page] -eq $script:LangCode) { return }
    $txtProgressLabel.Text = T 'catLoading'
    [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background)
    Initialize-CatPage $page $script:CatHosts[$page] ($page -eq 'power')
    $txtProgressLabel.Text = T 'ready'
}

# ------------------------------------------------------------------------------
# 29. APP E SOFTWARE: catalogo da installare e programmi installati
# ------------------------------------------------------------------------------
# Le installazioni passano da winget, il gestore di pacchetti di Windows: niente
# download da siti di terze parti. Le operazioni partono una alla volta in
# background e la finestra resta utilizzabile mentre lavorano.

$radAppsCatalog = E 'radAppsCatalog'; $radAppsInstalled = E 'radAppsInstalled'
$txtAppSearch = E 'txtAppSearch'; $lblAppSearchHint = E 'lblAppSearchHint'
$cmbAppCategory = E 'cmbAppCategory'; $cmbAppLicense = E 'cmbAppLicense'
$btnAppsAction = E 'btnAppsAction'; $btnAppsUpgrade = E 'btnAppsUpgrade'
$btnAppsClear = E 'btnAppsClear'; $btnAppsRefresh = E 'btnAppsRefresh'
$txtAppsStatus = E 'txtAppsStatus'; $panApps = E 'panApps'

$script:AppSel = New-Object 'System.Collections.Generic.HashSet[string]'
$script:AppInstalledIds = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$script:AppInstalledList = @()
$script:AppJobs = New-Object System.Collections.Queue
$script:AppProc = $null
$script:AppJob = $null
$script:AppExport = $null
$script:AppsReady = $false
$script:Winget = $null
try { $script:Winget = (Get-Command winget.exe -ErrorAction Stop).Source } catch {}

$script:AppLicColors = @{
    os = @('#FF2ED3A7', '#262ED3A7'); fw = @('#FF7DD3FC', '#2638BDF8'); fr = @('#FFFDBA74', '#26FDBA74')
    ms = @('#FFA5B4FC', '#26818CF8'); pd = @('#FFF87171', '#26F87171')
}

function New-AppBrush([string]$hex) { New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString($hex)) }

function New-AppPill([string]$text, [string]$fg, [string]$bg) {
    $b = New-Object System.Windows.Controls.Border
    $b.CornerRadius = 6; $b.Padding = '7,2,7,2'; $b.Margin = '8,0,0,0'; $b.VerticalAlignment = 'Center'
    $b.Background = New-AppBrush $bg
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $text; $t.FontSize = 10.5; $t.FontWeight = 'SemiBold'; $t.Foreground = New-AppBrush $fg
    $b.Child = $t
    return $b
}

# Riga di un'app: nome e descrizione a sinistra, etichette e interruttore a destra.
function New-AppRow([string]$key, [string]$title, [string]$sub, [array]$pills) {
    $g = New-Object System.Windows.Controls.Grid
    $g.Margin = '10,5,0,5'
    foreach ($w in @('*', 'Auto', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = if ($w -eq '*') { New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star) } else { [System.Windows.GridLength]::Auto }
        $g.ColumnDefinitions.Add($cd)
    }
    $sp = New-Object System.Windows.Controls.StackPanel; $sp.VerticalAlignment = 'Center'
    $t1 = New-Object System.Windows.Controls.TextBlock
    $t1.Text = $title; $t1.FontSize = 13; $t1.FontWeight = 'SemiBold'; $t1.Foreground = New-AppBrush '#FFE8E8EE'; $t1.TextTrimming = 'CharacterEllipsis'
    $t2 = New-Object System.Windows.Controls.TextBlock
    $t2.Text = $sub; $t2.FontSize = 11.5; $t2.Foreground = New-AppBrush '#FF8E8E98'; $t2.TextWrapping = 'Wrap'; $t2.Margin = '0,2,0,0'
    [void]$sp.Children.Add($t1); if ($sub) { [void]$sp.Children.Add($t2) }
    [void]$g.Children.Add($sp)
    $pp = New-Object System.Windows.Controls.StackPanel; $pp.Orientation = 'Horizontal'; $pp.VerticalAlignment = 'Center'
    foreach ($p in $pills) { [void]$pp.Children.Add($p) }
    [System.Windows.Controls.Grid]::SetColumn($pp, 1); [void]$g.Children.Add($pp)
    $cb = New-Object System.Windows.Controls.CheckBox
    $cb.Content = ''; $cb.Tag = $key; $cb.Margin = '4,0,0,0'; $cb.HorizontalAlignment = 'Right'; $cb.Width = 64
    $cb.IsChecked = $script:AppSel.Contains($key)
    $cb.Add_Checked({ [void]$script:AppSel.Add([string]$this.Tag); Update-AppButtons })
    $cb.Add_Unchecked({ [void]$script:AppSel.Remove([string]$this.Tag); Update-AppButtons })
    [System.Windows.Controls.Grid]::SetColumn($cb, 2); [void]$g.Children.Add($cb)
    return $g
}

function New-AppCard([string]$title) {
    $card = New-Object System.Windows.Controls.Border
    $card.Style = $window.FindResource('Glass')
    $sp = New-Object System.Windows.Controls.StackPanel
    $h = New-Object System.Windows.Controls.TextBlock
    $h.Text = $title.ToUpper(); $h.Style = $window.FindResource('CardTitle')
    [void]$sp.Children.Add($h)
    $card.Child = $sp
    return @{ Card = $card; Panel = $sp }
}

function Get-AppFilterText { return $txtAppSearch.Text.Trim() }

function Show-AppCatalog {
    $panApps.Children.Clear()
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($i in 0..1) { $cd = New-Object System.Windows.Controls.ColumnDefinition; $cd.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star); $grid.ColumnDefinitions.Add($cd) }
    $cols = @((New-Object System.Windows.Controls.StackPanel), (New-Object System.Windows.Controls.StackPanel))
    for ($i = 0; $i -lt 2; $i++) { [System.Windows.Controls.Grid]::SetColumn($cols[$i], $i); [void]$grid.Children.Add($cols[$i]) }
    $h = @(0, 0)
    $q = Get-AppFilterText
    $cat = if ($cmbAppCategory.SelectedItem) { [string]$cmbAppCategory.SelectedItem.Tag } else { '' }
    $lic = if ($cmbAppLicense.SelectedItem) { [string]$cmbAppLicense.SelectedItem.Tag } else { '' }
    $shown = 0
    foreach ($c in $script:AppCategories) {
        if ($cat -and $c.Key -ne $cat) { continue }
        $apps = @($script:AppCatalog | Where-Object {
            $_.Cat -eq $c.Key -and (-not $lic -or $_.Lic -eq $lic) -and
            (-not $q -or $_.Name -like "*$q*" -or (Get-Text $_.Desc) -like "*$q*")
        })
        if ($apps.Count -eq 0) { continue }
        $card = New-AppCard (T "appCat_$($c.Key)")
        foreach ($a in $apps) {
            $col = $script:AppLicColors[$a.Lic]
            $pills = @(New-AppPill (T "lic_$($a.Lic)") $col[0] $col[1])
            $wid = $a.Id -replace '^store:', ''
            if ($script:AppInstalledIds.Contains($wid)) { $pills += New-AppPill (T 'appInstalled') '#FF2ED3A7' '#1A2ED3A7' }
            [void]$card.Panel.Children.Add((New-AppRow $a.Id $a.Name (Get-Text $a.Desc) $pills))
            $shown++
        }
        $k = if ($h[0] -le $h[1]) { 0 } else { 1 }
        [void]$cols[$k].Children.Add($card.Card)
        $h[$k] += $apps.Count + 2
    }
    [void]$panApps.Children.Add($grid)
    if ($shown -eq 0) { $txtAppsStatus.Text = T 'appsNone' }
}

# Programmi installati: registro di disinstallazione e app dello Store.
function Get-InstalledApps {
    $list = New-Object System.Collections.ArrayList
    $roots = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'
    )
    $seen = @{}
    foreach ($r in $roots) {
        foreach ($k in @(Get-ChildItem -LiteralPath $r -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if (-not $p.DisplayName -or -not $p.UninstallString) { continue }
            if ($p.SystemComponent -eq 1 -or $p.ParentKeyName -or $p.ReleaseType -in @('Update','Hotfix','Security Update')) { continue }
            $sig = "$($p.DisplayName)|$($p.DisplayVersion)"
            if ($seen.ContainsKey($sig)) { continue }
            $seen[$sig] = $true
            [void]$list.Add([pscustomobject]@{
                Key = "w:$($k.PSPath)"; Name = [string]$p.DisplayName; Version = [string]$p.DisplayVersion
                Publisher = [string]$p.Publisher; Kind = 'Win32'
                Uninstall = [string]$p.UninstallString; Quiet = [string]$p.QuietUninstallString; Pkg = ''
            })
        }
    }
    try {
        foreach ($a in @(Get-AppxPackage -PackageTypeFilter Main -ErrorAction Stop | Where-Object { -not $_.NonRemovable -and $_.SignatureKind -ne 'System' })) {
            # Il nome leggibile sta nel manifest; se e' una risorsa da tradurre si ripiega
            # sul nome del pacchetto senza il prefisso dell'editore.
            $name = ([string]$a.Name -replace '^[0-9A-F]+[A-Za-z]*\.', '')
            $pub = ''
            try {
                [xml]$mf = [IO.File]::ReadAllText((Join-Path $a.InstallLocation 'AppxManifest.xml'))
                $dn = [string]$mf.Package.Properties.DisplayName
                $pd = [string]$mf.Package.Properties.PublisherDisplayName
                if ($dn -and $dn -notlike 'ms-resource:*') { $name = $dn }
                if ($pd -and $pd -notlike 'ms-resource:*') { $pub = $pd }
            } catch {}
            [void]$list.Add([pscustomobject]@{
                Key = "x:$($a.PackageFullName)"; Name = $name; Version = [string]$a.Version
                Publisher = $pub; Kind = 'Store'
                Uninstall = ''; Quiet = ''; Pkg = [string]$a.PackageFullName
            })
        }
    } catch {}
    return @($list | Sort-Object Name)
}

function Show-AppInstalled {
    $panApps.Children.Clear()
    $q = Get-AppFilterText
    $card = New-AppCard ((T 'appsInstalledTitle') -f $script:AppInstalledList.Count)
    foreach ($a in $script:AppInstalledList) {
        if ($q -and $a.Name -notlike "*$q*" -and $a.Publisher -notlike "*$q*") { continue }
        $sub = (@($a.Version, $a.Publisher) | Where-Object { $_ }) -join '  ·  '
        $pill = if ($a.Kind -eq 'Store') { New-AppPill 'Store' '#FFA5B4FC' '#26818CF8' } else { New-AppPill 'Win32' '#FFC4C4CC' '#1FFFFFFF' }
        [void]$card.Panel.Children.Add((New-AppRow $a.Key $a.Name $sub @($pill)))
    }
    [void]$panApps.Children.Add($card.Card)
}

function Update-AppButtons {
    $n = $script:AppSel.Count
    $label = if ($radAppsInstalled.IsChecked) { T 'appsUninstallSel' } else { T 'appsInstallSel' }
    $btnAppsAction.Content = if ($n -gt 0) { "$label ($n)" } else { $label }
    $busy = ($null -ne $script:AppProc) -or ($script:AppJobs.Count -gt 0)
    $btnAppsAction.IsEnabled = ($n -gt 0) -and -not $busy -and ($radAppsInstalled.IsChecked -or $script:Winget)
    $btnAppsUpgrade.IsEnabled = ($null -ne $script:Winget) -and -not $busy
    $btnAppsAction.Tag = if ($radAppsInstalled.IsChecked) { New-AppBrush '#FFF87171' } else { New-AppBrush '#FF2ED3A7' }
}

function Show-AppView {
    if ($radAppsInstalled.IsChecked) {
        $cmbAppCategory.Visibility = 'Collapsed'; $cmbAppLicense.Visibility = 'Collapsed'
        if ($script:AppInstalledList.Count -eq 0) { $script:AppInstalledList = Get-InstalledApps }
        Show-AppInstalled
    } else {
        $cmbAppCategory.Visibility = 'Visible'; $cmbAppLicense.Visibility = 'Visible'
        Show-AppCatalog
    }
    Update-AppButtons
}

function Initialize-AppFilters {
    $keepCat = if ($cmbAppCategory.SelectedItem) { [string]$cmbAppCategory.SelectedItem.Tag } else { '' }
    $keepLic = if ($cmbAppLicense.SelectedItem) { [string]$cmbAppLicense.SelectedItem.Tag } else { '' }
    $script:AppFiltersLoading = $true
    $cmbAppCategory.Items.Clear(); $cmbAppLicense.Items.Clear()
    $all = New-Object System.Windows.Controls.ComboBoxItem; $all.Tag = ''; $all.Content = T 'appsAllCategories'; [void]$cmbAppCategory.Items.Add($all)
    foreach ($c in $script:AppCategories) {
        $ci = New-Object System.Windows.Controls.ComboBoxItem; $ci.Tag = $c.Key; $ci.Content = T "appCat_$($c.Key)"
        [void]$cmbAppCategory.Items.Add($ci)
        if ($c.Key -eq $keepCat) { $cmbAppCategory.SelectedItem = $ci }
    }
    if ($null -eq $cmbAppCategory.SelectedItem) { $cmbAppCategory.SelectedIndex = 0 }
    foreach ($l in @('', 'os', 'fw', 'fr', 'ms', 'pd')) {
        $ci = New-Object System.Windows.Controls.ComboBoxItem; $ci.Tag = $l
        $ci.Content = if ($l) { T "lic_$l" } else { T 'appsAllLicenses' }
        [void]$cmbAppLicense.Items.Add($ci)
        if ($l -eq $keepLic) { $cmbAppLicense.SelectedItem = $ci }
    }
    $script:AppFiltersLoading = $false
}

# --- esecuzione in background, un processo alla volta ---
function Add-AppJob([string]$label, [string]$file, [string]$arguments) {
    $script:AppJobs.Enqueue(@{ Label = $label; File = $file; Args = $arguments })
}

$script:AppTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:AppTimer.Interval = [TimeSpan]::FromMilliseconds(600)
$script:AppTimer.Add_Tick({
    if ($null -ne $script:AppExport -and $script:AppExport.HasExited) { Complete-AppExport }
    if ($null -ne $script:AppProc) {
        if (-not $script:AppProc.HasExited) { return }
        $code = $script:AppProc.ExitCode
        # -1978335189 e -1978335135: gia' installato o nessun aggiornamento, non sono errori.
        if ($code -eq 0 -or $code -eq -1978335189 -or $code -eq -1978335135) { Write-Log "[OK] $($script:AppJob.Label)" }
        else { Write-Log "[ERRORE] $($script:AppJob.Label) - codice $code" }
        $script:AppProc = $null
    }
    if ($script:AppJobs.Count -gt 0) {
        $script:AppJob = $script:AppJobs.Dequeue()
        $txtAppsStatus.Text = (T 'appsWorking') -f $script:AppJob.Label, $script:AppJobs.Count
        try {
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName = $script:AppJob.File; $psi.Arguments = $script:AppJob.Args
            $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
            $script:AppProc = [System.Diagnostics.Process]::Start($psi)
        } catch {
            Write-Log "[ERRORE] $($script:AppJob.Label) - $($_.Exception.Message)"
            $script:AppProc = $null
        }
        Update-AppButtons
        return
    }
    if ($null -eq $script:AppExport) {
        $script:AppTimer.Stop()
        if ($script:AppJob) {
            $script:AppJob = $null
            $txtAppsStatus.Text = T 'appsDone'
            $script:AppInstalledList = @()
            Start-AppExport
            Show-AppView
        }
    }
    Update-AppButtons
})

# Elenco degli id winget installati: winget export scrive un file JSON.
function Start-AppExport {
    if (-not $script:Winget -or $null -ne $script:AppExport) { return }
    $script:AppExportFile = Join-Path $env:TEMP 'TweakAndrew_winget.json'
    Remove-Item -LiteralPath $script:AppExportFile -ErrorAction SilentlyContinue
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $script:Winget
        $psi.Arguments = "export -o `"$($script:AppExportFile)`" --accept-source-agreements --disable-interactivity"
        $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
        $script:AppExport = [System.Diagnostics.Process]::Start($psi)
        $txtAppsStatus.Text = T 'appsChecking'
        $script:AppTimer.Start()
    } catch { $script:AppExport = $null }
}

function Complete-AppExport {
    $script:AppExport = $null
    $script:AppInstalledIds.Clear()
    try {
        $j = Get-Content -LiteralPath $script:AppExportFile -Raw -ErrorAction Stop | ConvertFrom-Json
        foreach ($s in $j.Sources) { foreach ($p in $s.Packages) { [void]$script:AppInstalledIds.Add([string]$p.PackageIdentifier) } }
    } catch {}
    if (-not $script:AppJob) { $txtAppsStatus.Text = (T 'appsInstalledCount') -f $script:AppInstalledIds.Count }
    if (-not $radAppsInstalled.IsChecked) { Show-AppCatalog }
}

function Get-UninstallCommand($a) {
    if ($a.Kind -eq 'Store') {
        return @('powershell.exe', "-NoProfile -Command `"Remove-AppxPackage -Package '$($a.Pkg)'`"")
    }
    if ($a.Uninstall -match '(?i)msiexec(\.exe)?\s+/[IX]\s*(\{[0-9A-F\-]+\})') {
        return @('msiexec.exe', "/x $($Matches[2]) /qb /norestart")
    }
    $cmd = if ($a.Quiet) { $a.Quiet } else { $a.Uninstall }
    return @('cmd.exe', "/c `"$cmd`"")
}

$btnAppsAction.Add_Click({
    $n = $script:AppSel.Count
    if ($n -eq 0) { return }
    if ($radAppsInstalled.IsChecked) {
        if (-not (Show-Dialog (T 'confirmTitle') ((T 'appsAskUninstall') -f $n) 'danger')) { return }
        foreach ($a in @($script:AppInstalledList | Where-Object { $script:AppSel.Contains($_.Key) })) {
            $c = Get-UninstallCommand $a
            Add-AppJob "$(T 'appsUninstalling') $($a.Name)" $c[0] $c[1]
        }
    } else {
        if (-not (Show-Dialog (T 'confirmTitle') ((T 'appsAskInstall') -f $n) 'ask')) { return }
        foreach ($a in @($script:AppCatalog | Where-Object { $script:AppSel.Contains($_.Id) })) {
            $src = if ($a.Id -like 'store:*') { 'msstore' } else { 'winget' }
            $id = $a.Id -replace '^store:', ''
            Add-AppJob "$(T 'appsInstalling') $($a.Name)" $script:Winget "install --id $id -e --source $src --silent --accept-package-agreements --accept-source-agreements --disable-interactivity"
        }
    }
    $script:AppSel.Clear()
    Show-AppView
    $script:AppTimer.Start()
})

$btnAppsUpgrade.Add_Click({
    if (-not (Show-Dialog (T 'confirmTitle') (T 'appsAskUpgrade') 'ask')) { return }
    Add-AppJob (T 'appsUpgradeAll') $script:Winget 'upgrade --all --silent --accept-package-agreements --accept-source-agreements --disable-interactivity'
    $script:AppTimer.Start()
    Update-AppButtons
})

$btnAppsClear.Add_Click({ $script:AppSel.Clear(); Show-AppView })
$btnAppsRefresh.Add_Click({ $script:AppInstalledList = @(); Start-AppExport; Show-AppView })
$radAppsCatalog.Add_Checked({ if ($script:AppsReady) { $script:AppSel.Clear(); Show-AppView } })
$radAppsInstalled.Add_Checked({ if ($script:AppsReady) { $script:AppSel.Clear(); Show-AppView } })
$cmbAppCategory.Add_SelectionChanged({ if ($script:AppsReady -and -not $script:AppFiltersLoading) { Show-AppCatalog } })
$cmbAppLicense.Add_SelectionChanged({ if ($script:AppsReady -and -not $script:AppFiltersLoading) { Show-AppCatalog } })
$txtAppSearch.Add_TextChanged({
    $lblAppSearchHint.Visibility = if ($txtAppSearch.Text) { 'Collapsed' } else { 'Visible' }
    if ($script:AppsReady) { Show-AppView }
})

# Prima apertura della pagina: filtri, catalogo e controllo delle app gia' presenti.
function Show-AppsPageIfNeeded {
    if ($script:AppsBuiltLang -eq $script:LangCode) { return }
    $script:AppsBuiltLang = $script:LangCode
    Initialize-AppFilters
    $script:AppsReady = $true
    Show-AppView
    if (-not $script:Winget) {
        $txtAppsStatus.Text = T 'appsNoWinget'
    } elseif ($script:AppInstalledIds.Count -eq 0) { Start-AppExport }
}


# ------------------------------------------------------------------------------
# 20. AVVIO
# ------------------------------------------------------------------------------
Show-GpuInfo
Update-PowerPlanLabel
Show-PlanList
$script:UiReady = $true

Write-Log "[INFO] Tweak Andrew v7.1 pronto. Il registro dettagliato resta in questa finestra."

[void]$window.ShowDialog()
